(window.GIM_TS=window.GIM_TS||{})["Megillah.2"]={"from":48,"a":[["— \u0003יקחו\u0004 במחירן \u0003ספרים\u0004 של נביאים וכתובים. מכרו \u0003ספרים\u0004 — \u0003לוקחין\u0004 ספר \u0003תורה.\u0004 שבכל אחד מן המקרים מעלים בקודש, וקונים דבר שהוא מקודש יותר ממה שנמכר.","\u0003אבל\u0004 לא יעשו להיפך, להוריד בקודש, ש\u0003אם מכרו\u0004 ספר \u0003תורה\u0004 — \u0003לא יקחו ספרים.\u0004 מכרו \u0003ספרים\u0004 — \u0003לא יקחו מטפחות.\u0004 מכרו \u0003מטפחות\u0004 — \u0003לא יקחו תיבה.\u0004 מכרו \u0003תיבה\u0004 — \u0003לא יקחו בית הכנסת.\u0004 מכרו את \u0003בית הכנסת\u0004 — \u0003לא יקחו את הרחוב.\u0004","\u0003וכן\u0004 הדין \u0003במותריהן,\u0004 שאם מכרו וקנו דבר שמותר להם לקנותו ונשאר סכום כסף עודף — אף בעודף זה אין משתמשים אלא לקדושה מעולה יותר, ולא לקדושה פחותה.","שנינו: \u0003בני העיר שמכרו רחובה של עיר\u0004 — יקנו בדמיו בית כנסת. \u0003אמר רבה בר בר חנה אמר ר' יוחנן:\u0004 משנתנו \u0003זו\u0004 כדברי \u0003ר' מנחם בר יוסי סתומתאה\u0004 \u0005[הסותם],\u0006 שכמה מהלכותיו נכתבו במשנה כסתם, ללא שם אומרן, ואף הוא אמר כהלכה זו בתוספתא, \u0003אבל חכמים אומרים: הרחוב אין בו\u0004 כלל \u0003משום קדושה,\u0004 ואם מוכרים אותו, אפשר לעשות בדמיו מה שרוצים.","ושואלים: \u0003ור' מנחם בר יוסי מאי טעמיה\u0004 \u0005[מהו טעמו]?\u0006 ומשיבים: \u0003הואיל והעם מתפללים בו בתעניות ובמעמדות,\u0004 לכן יש בו מקצת קדושה. \u0003ורבנן\u0004 \u0005[וחכמים]\u0006 מה הם אומרים — לדעתם הדבר \u0003ההוא,\u0004 תפילת הרבים ברחובה של עיר הוא אירוע \u0003אקראי בעלמא\u0004 \u0005[מקרי בלבד]\u0006 ולא בקביעות, ואין שימוש ארעי במקום מסויים לצורך דבר שבקדושה, עושהו למקום מקודש.","שנינו במשנה: אם מכרו \u0003בית הכנסת\u0004 — \u0003לוקחין\u0004 בדמיו \u0003תיבה. אמר ר' שמואל בר נחמני אמר ר' יונתן: לא שנו\u0004 שמוכרים בית כנסת \u0003אלא בית הכנסת של כפרים\u0004 שהוא רכושו של הכפר, \u0003אבל בית הכנסת של כרכים, כיון דמעלמא אתו ליה\u0004 \u0005[שמן העולם,\u0006 מן החוץ \u0005באים אליו],\u0006 לכך \u0003לא מצו מזבני ליה\u0004 \u0005[אין\u0006 בני הכרך \u0005יכולים למכור אותו].\u0006 וטעמו: כיון \u0003דהוה ליה\u0004 \u0005[שהריהו]\u0006 דבר השייך ל\u0003רבים,\u0004 שאינו שייך לבני הכרך אלא הוא רכוש ציבורי, של העם כולו.","\u0003אמר רב אשי: האי בי כנישתא\u0004 \u0005[בית כנסת זה]\u0006 של עירי \u0003מתא מחסיא, אף על גב דמעלמא אתו לה\u0004 \u0005[אף על פי שמן העולם,\u0006 מן החוץ \u0005באים אליו],\u0006 \u0003כיון דאדעתא דידי קאתו\u0004 \u0005[שעל דעתי\u0006 שלי \u0005הם באים]\u0006 (כיון שהוא בנה אותו, והכל שם נעשה רק על פיו), לכך \u0003אי בעינא מזבנינא לה\u0004 \u0005[אם רוצה אני, יכול אני למכור אותו].\u0006","\u0003מיתיבי\u0004 \u0005[מקשים]\u0006 על דברי ר' שמואל בר נחמני מברייתא, \u0003אמר ר' יהודה: מעשה בבית הכנסת של טורסיים\u0004 (חרשי נחושת) \u0003שהיה בירושלים שמכרוה לר' אליעזר ועשה בה כל צרכיו, והא התם\u0004 \u0005[והרי שם]\u0006 בית כנסת של \u0003כרכים הוה\u0004 \u0005[היה]\u0006 זה, והרי שניתן למכירה! ומשיבים: \u0003ההיא, בי כנישתא זוטי הוה, ואינהו עבדוה\u0004 \u0005[ההוא, בית כנסת קטן היה, והם\u0006 הטורסיים \u0005עשו אותו]\u0006 והיה שייך רק להם, ולכן היו רשאים למכור אותו.","ומקשים על כך ממקום אחר, נאמר בדיני נגעים: \u0003\"\u0004ונתתי נגע צרעת \u0003בבית ארץ אחזתכם\"\u0004 (ויקרא יד, לד), ולמדו מכאן: \u0003אחוזתכם,\u0004 כלומר, מקום השייך לאדם פרטי כאחוזתו, \u0003מיטמא בנגעים, ואין ירושלים מיטמא בנגעים,\u0004 כיון אינה נחשבת כרשות פרטית השייכת לאדם או לשבט מסויים, אלא היא שייכת לכלל ישראל. \u0003אמר ר' יהודה: אני לא שמעתי\u0004 בדין זה \u0003אלא מקום מקדש בלבד\u0004 שהוא השייך לרבים, אבל לא העיר ירושלים.","ונדייק: \u0003הא\u0004 \u0005[הרי]\u0006 ש\u0003בתי כנסיות ובתי מדרשות\u0004 שבירושלים \u0003מיטמאים,\u0004 ו\u0003אמאי\u0004 \u0005[ומדוע]?\u0006 \u0003הא\u0004 \u0005[הרי]\u0006 של \u0003כרכין הוו\u0004 \u0005[הם],\u0006 וכפי שאמרנו בתי כנסת של כרכים הם רכוש העם ולא רכוש פרטי, אף לא של שותפים! ומתקנים: \u0003אימא\u0004 \u0005[תקן ואמור]\u0006 כך, \u0003אמר ר' יהודה: אני לא שמעתי אלא מקום מקודש בלבד,\u0004 ובכלל זה אף בתי הכנסת הגדולים השייכים לכלל.","לגופה של אותה מחלוקת בין ר' יהודה וחכמים, שואלים: \u0003במאי קמיפלגי\u0004 \u0005[במה,\u0006 באיזו סברה עקרונית \u0005נחלקו]?\u0006 ומסבירים: ה\u0003תנא קמא\u0004 \u0005[הראשון]\u0006 \u0003סבר\u0004 \u0005[סבור]:\u0006 \u0003לא נתחלקה ירושלים לשבטים,\u0004 שהעיר ירושלים לא היתה מעולם בתחום נחלתו של שבט מסויים, אלא היא שייכת לכלל ישראל, \u0003ור' יהודה סבר: נתחלקה ירושלים לשבטים,\u0004 ורק מקום המקדש הוא שלא נתחלק.","ומעירים, שהדבר קשור \u0003בפלוגתא דהני תנאי\u0004 \u0005[במחלוקתם\u0006 של \u0005אותם תנאים]\u0006 שנחלקו באותה בעיה,","\u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא אחת\u0005]:\u0006 \u0003מה היה בחלקו של יהודה — הר הבית\u0004 כולו, ו\u0003הלשכות\u0004 של המקדש, \u0003והעזרות\u0004 של המקדש. \u0003ומה היה בחלקו של בנימין\u0004 — \u0003אולם, והיכל, ובית קדשי הקדשים,\u0004","\u0003ורצועה היתה יוצאת מחלקו של יהודה ונכנסת בחלקו של בנימין, ובה\u0004 באותה רצועה היה ה\u0003מזבח בנוי, והיה בנימין הצדיק מצטער עליה בכל יום לבולעה,\u0004 כלומר, אנשי שבט בנימין היו מצטערים ומנסים לקבל בחלקם את החלק הקטן הזה של יהודה שנעשה מקום מקודש ביותר, \u0003שנאמר\u0004 בברכת משה לבנימין: \u0003\"חפף עליו כל היום\u0004 ובין כתפיו שכן\u0003\"\u0004 (דברים לג, יב), שמפרשים \"חופף\" במובן מצטער, משום שהדבר הזה היה מציק לו, ו\u0003לפיכך\u0004 מפני שהצטער על כך, \u0003זכה בנימין ונעשה אושפיזכן\u0004 \u0005[מארח]\u0006 \u0003לשכינה\u0004 שבית קודש הקדשים נבנה בחלקו.","הרי זו שיטת תנא הסבור שכל ירושלים, ואפילו מקום המקדש, נחלקו לשבטים, \u0003ו\u0004אילו \u0003האי תנא סבר\u0004 \u0005[תנא זה סבור]\u0006 ש\u0003לא נתחלקה ירושלים לשבטים. דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003אין משכירין בתים בירושלים, מפני ש\u0004הבתים \u0003אינן שלהם\u0004 של בעלי הבתים, שאף בעלי הבתים אינם אלא בבחינת דיירים, שכן אין לאיש אחוזת נחלה בעיר. \u0003ר' אלעזר בר צדוק אומר: אף לא\u0004 משכירים \u0003מטות. לפיכך, עורות קדשים\u0004 שהיו נוהגים אנשים הבאים לירושלים לתת לבעלי האכסניא כתמורה על האיכסון, \u0003בעלי אושפיזין\u0004 (אכסניות) שבירושלים \u0003נוטלים אותם בזרוע\u0004 (בכוח, בגזל), שהרי אין להם בעלות אמיתית על דירותיהם.","\u0003אמר אביי: שמע מינה\u0004 \u0005[נלמד מכאן]\u0006 בדרך אגב כי \u0003אורח ארעא למישבק אינש גולפא ומשכא באושפיזיה\u0004 \u0005[דרך ארץ\u0006 היא \u0005שיעזוב אדם את הכד\u0006 של היין שהשתמש בו \u0005ואת העור\u0006 של הבהמה ששחט לאוכלה \u0005בבית המלון שלו]\u0006 כמתנה.","\u0003אמר רבא: לא שנו\u0004 שיש קדושה בכספים שקיבלו בני העיר עבור בית כנסת או חפצי קודש, \u0003אלא\u0004 דווקא כ\u0003שלא מכרו\u0004 אותם \u0003שבעה טובי העיר\u0004 שהם הממונים הרשמיים שנבחרו באותה עיר \u0003במעמד\u0004 כל \u0003אנשי העיר, אבל\u0004 אם \u0003מכרו שבעה טובי העיר במעמד אנשי העיר,\u0004 יש להם זכות להפקיע את הקדושה מן המקום ו\u0003אפילו\u0004"],["\u0003למישתא ביה שיכרא\u0004 \u0005[לשתות בו,\u0006 במחירו \u0005שיכר]\u0006 — \u0003שפיר דמי\u0004 \u0005[ראוי הדבר\u0006 ומותר\u0005],\u0006 שכיון שכולם הסכימו בדבר, יכולים הם לחלל את הקדושה על כל מה שירצו.","מסופר: \u0003רבינא הוה ליה ההוא תילא דבי כנישתא\u0004 \u0005[היה לו\u0006 ברשותו \u0005תל אחד,\u0006 חורבה, \u0005של בית הכנסת],\u0006 \u0003אתא לקמיה\u0004 \u0005[בא לפני]\u0006 \u0003רב אשי, אמר ליה\u0004 \u0005[לו]:\u0006 \u0003מהו\u0004 הדין, האם מותר \u0003למיזרעה\u0004 \u0005[לזרוע אותו]?\u0006 \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003זיל זבניה\u0004 \u0005[לך קנה אותו]\u0006 \u0003משבעה טובי העיר במעמד אנשי העיר וזרעה\u0004 \u0005[וזרע אותה].\u0006","ומסופר עוד: \u0003רמי בר אבא הוה קא בני בי כנישתא\u0004 \u0005[היה בונה בית הכנסת],\u0006 \u0003הוה ההיא כנישתא עתיקא, הוה בעי למיסתריה ולאתויי ליבני וכשורי מינה ועיולי להתם\u0004 \u0005[היה בית כנסת ישן שרצה להרוס אותו ולהביא לבנים וקורות ממנו ולהכניס לשם\u0006 לבנין החדש\u0005].\u0006 \u0003יתיב וקא מיבעיא ליה\u0004 \u0005[ישב ונסתפק לו]\u0006 \u0003הא\u0004 \u0005[\u0006בדבר הלכה \u0005זה]\u0006 שאמר \u0003רב חסדא,\u0004 ש\u0003אמר רב חסדא: לא ליסתור\u0004 \u0005[יסתור]\u0006 אדם \u0003בי כנישתא\u0004 \u0005[בית כנסת]\u0006 \u0003עד דבני בי כנישתא אחריתי\u0004 \u0005[שבונה בית כנסת אחר],\u0006 ונסתפק לרמי בר אבא האם \u0003התם\u0004 \u0005[שם]\u0006 החשש הוא \u0003משום פשיעותא\u0004 \u0005[רשלנות],\u0006 שמא יסתרו את הראשון ולא יבנו את השני, ואם כן, \u0003כי האי גוונא מאי\u0004 \u0005[באופן זה\u0006 שסתירתו של הראשון לצורך בניית השני \u0005מהו]?\u0006 \u0003אתא לקמיה\u0004 \u0005[בא לפני]\u0006 \u0003רב פפא\u0004 לשאול אותו — \u0003ואסר ליה\u0004 \u0005[לו].\u0006 לאחר מכן בא \u0003לקמיה\u0004 \u0005[לפני]\u0006 \u0003רב הונא ו\u0004אף הוא \u0003אסר ליה.\u0004","ועוד \u0003אמר רבא: האי בי כנישתא\u0004 \u0005[בית כנסת זה]\u0006 \u0003חלופה וזבונה\u0004 \u0005[להחליף אותו\u0006 בבנין אחר \u0005ולמכור אותו] —\u0006 \u0003שרי\u0004 \u0005[מותר],\u0006 אבל \u0003אוגורה ומשכונה —\u0004 \u0005[להשכיר אותו או למשכן אותו]\u0006 \u0003אסור. מאי טעמא\u0004 \u0005[מה טעם] —\u0006 \u0003בקדושתה קאי\u0004 \u0005[בקדושתו\u0006 הוא \u0005עומד],\u0006 שהרי אם הוא מוכרו או מחליף אותו בבנין אחר, הקדושה חלה על בית הכנסת החדש או על הכסף ונפקעת מן הראשון. מה שאין כן כשמשכירים אותו לא נעקרה ממנו קדושתו הקודמת.","\u0003ליבני נמי\u0004 \u0005[לבנים\u0006 של בית הכנסת \u0005גם כן]\u0006 \u0003חלופינהו וזבונינהו\u0004 \u0005[להחליף אותן או למכור אותן]\u0006 — \u0003שרי\u0004 \u0005[מותר],\u0006 אבל \u0003אוזופינהו\u0004 \u0005[להשאיל אותן] —\u0006 \u0003אסור.\u0004 ומעירים: \u0003הני מילי בעתיקתא\u0004 \u0005[דברים אלו\u0006 אמורים דווקא \u0005ב\u0006לבנים \u0005עתיקות]\u0006 שהיו כבר בבית הכנסת, \u0003אבל בחדתא, לית לן בה\u0004 \u0005[ב\u0006לבנים \u0005חדשות, אין לנו בה\u0006 איסור\u0005].\u0006","\u0003ואפילו ל\u0004שיטת \u0003מאן דאמר\u0004 \u0005[מי שאומר]\u0006 את הכלל: \u0003הזמנה\u0004 הכנה \u0003מילתא\u0004 \u0005[דבר]\u0006 \u0003היא,\u0004 כלומר, אם מכינים דבר־מה לצורך מסויים, הריהו נחשב כאילו כבר השתמשו בו, הן לענין קדושה והן לענין איסור, אולם \u0003הני מילי\u0004 \u0005[דברים אלו]\u0006 אמורים \u0003כגון האורג בגד למת,\u0004 שבשעת האריגה ראוי כבר לשימוש עבור המת ונאסר בהנאה כמו כל תכריכי המת. \u0003אבל הכא\u0004 \u0005[כאן]\u0006 בלבנים, \u0003כטווי לאריג דמי\u0004 \u0005[נחשב],\u0006 ואם רק טווה חוטים לצורך אריג שממנו יתפרו בגד למת, כל עוד לא ארג אותם עדיין עשויים הם לשמש לכל מטרה ואינם אסורים, וכמו כן גם בלבנים, שכל עוד לא בנאן בכותל אינן נחשבות כדבר הראוי לשימוש מיידי, ובדבר כגון זה \u0003ליכא למאן דאמר\u0004 \u0005[אין מי שאומר]\u0006 שההזמנה בעצמה מועילה, אלא אם כן השתמשו בפועל בחפץ.","בשאלה אם נותנים בית כנסת או דבר שבקדושה ב\u0003מתנה, פליגי\u0004 \u0005[נחלקו]\u0006 \u0003בה רב אחא ורבינא, חד\u0004 \u0005[אחד\u0006 מהם\u0005]\u0006 \u0003אסר, וחד שרי\u0004 \u0005[ואחד\u0006 מהם \u0005התיר].\u0006 ומבארים את השיטות: \u0003מאן דאסר\u0004 \u0005[מי שאוסר]\u0006 סבור: \u0003בהאי\u0004 \u0005[בזה]\u0006 \u0003תפקע קדושתה?!\u0004 הרי לא היה דבר שיחול עליו הפדיון שתעבור עליו קדושת בית הכנסת. \u0003ומאן דשרי\u0004 \u0005[ומי שמתיר]\u0006 סבור כי גם במתנה \u0003אי לאו דהוה ליה\u0004 \u0005[אם לא שהיתה לו\u0006 למקבל המתנה\u0005]\u0006 \u0003הנאה מיניה\u0004 \u0005[ממנו]\u0006 \u0003לא הוה יהיב ליה\u0004 \u0005[היה נותן לו\u0006 מתנה\u0005],\u0006 ואם כן \u0003הדר הוה ליה\u0004 \u0005[חזרה,\u0006 הפכה \u0005להיות]\u0006 ה\u0003מתנה כזביני\u0004 \u0005[כמכר],\u0006 שמתנה היא כעין מכר, ואף שאין שויון גמור בין ההנאה והנתינה, הרי זה מעין חליפין.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003תשמישי מצוה,\u0004 כלומר, דברים ששימשו לצורך מצוה, לאחר שעשו בהם מצותם — \u0003נזרקין\u0004 ואין צורך לגנוז אותם. \u0003תשמישי קדושה,\u0004 דברים שהשתמשו בהם לצורך קדושה (בעיקר — כתבי הקודש), גם לאחר שאינם משמשים עוד — \u0003נגנזין\u0004 בכבוד. ומפרטים, \u0003ואלו הן תשמישי מצוה:\u0004 כגון, \u0003סוכה, לולב, שופר, ציצית. ואלו הם תשמישי קדושה:\u0004 כגון, \u0003דלוסקמי\u0004 (ארגזים) של \u0003ספרים, תפילין ומזוזות, ותיק\u0004 (נרתיק) \u0003של ספר תורה, ונרתיק של תפילין ורצועותיהן\u0004 של תפילין.","בהקשר לאותו ענין \u0003אמר רבא: מריש הוה אמינא\u0004 \u0005[בראשונה הייתי אומר]:\u0006 \u0003האי כורסיא\u0004 \u0005[כיסא,\u0006 במה \u0005זו\u0006 שבבית הכנסת\u0005]\u0006 הוא רק \u0003תשמיש\u0004 של \u0003תשמיש הוא, ו\u0004משבלה ושוב אינו ראוי לשימוש \u0003שרי\u0004 \u0005[מותר]\u0006 בזריקה, מפני שאת ספר התורה אין מניחים במישרין על הבמה, אלא על גבי מפה הפרוסה עליה. \u0003כיון דחזינא דמותבי עלויה\u0004 \u0005[כיון שראיתי ש\u0006לפעמים \u0005מניחים עליה]\u0006 \u0003ספר תורה\u0004 עצמו, \u0003אמינא\u0004 \u0005[אמרתי]:\u0006 \u0003תשמיש קדושה הוא — ואסור.\u0004","וכיוצא בו \u0003אמר רבא: מריש הוה אמינא, האי פריסא\u0004 \u0005[בראשונה הייתי אומר,\u0006 ש\u0005אותה היריעה\u0006 שפורסים בתוך ארון הקודש לקישוט\u0005]\u0006 רק \u0003תשמיש\u0004 של \u0003תשמיש\u0004 קדושה \u0003הוא. כיון דחזינא דעייפי ליה ומנחי סיפרא עלויה\u0004 \u0005[שראיתי ש\u0006לפעמים \u0005מקפלים אותה ומניחים ספר\u0006 תורה \u0005עליה],\u0006 \u0003אמינא\u0004 \u0005[אמרתי]:\u0006 \u0003תשמיש קדושה הוא ואסור.\u0004","\u0003ואמר רבא: האי תיבותא דאירפט\u0004 \u0005[ארון קודש זה שהתבלה],\u0006 \u0003מיעבדה תיבה זוטרתי\u0004 \u0005[לעשות\u0006 ממנו \u0005ארון קטן] —\u0006 \u0003שרי\u0004 \u0005[מותר],\u0006 אבל לעשות ממנו \u0003כורסייא\u0004 \u0005[כיסא,\u0006 במה\u0005]\u0006 — \u0003אסיר\u0004 \u0005[אסור],\u0006 משום שזו ירידה בקדושתה. \u0003ואמר רבא: האי פריסא דבלה\u0004 \u0005[יריעה זו\u0006 שמקשטת את הארון \u0005שבלתה],\u0006 \u0003למיעבדיה פריסא\u0004 \u0005[לעשות אותה מפה]\u0006 \u0003לספרי\u0004 התורה — \u0003שרי\u0004 \u0005[מותר],\u0006 ואולם לעשות ממנה מפה \u0003לחומשין — אסור.\u0004","\u0003ואמר רבא: הני זבילי דחומשי\u0004 \u0005[ארגזים ש\u0006מניחים בהם \u0005חומשים],\u0006 \u0003וקמטרי\u0004 \u0005[ותיקים]\u0006 של \u0003ספרי\u0004 תורה — \u0003תשמישי קדושה נינהו\u0004 \u0005[הם]\u0006 \u0003ונגנזין.\u0004 ושואלים: \u0003פשיטא\u0004 \u0005[פשוט,\u0006 מובן שכן הוא\u0005]!\u0006 ומשיבים: \u0003מהו דתימא\u0004 \u0005[שתאמר]:\u0006 \u0003הני לאו\u0004 \u0005[\u0006ארגזים \u0005אלה לא]\u0006 \u0003לכבוד\u0004 הספרים \u0003עבידן\u0004 \u0005[\u0006הם \u0005עשויים]\u0006 אלא \u0003לנטורי בעלמא עבידי\u0004 \u0005[לשמירה בלבד\u0006 הם \u0005עשויים]\u0006 ולכן אינם נחשבים כתשמישו של ספר התורה, על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 שאף שהם משמשים גם לשמירה, מכל מקום נחשבים כתשמיש של כבוד.","מסופר: \u0003ההוא בי כנישתא דרומאי דהוה פתיח לההוא אידרונא דהוה מחית ביה\u0004 \u0005[בית כנסת אחד של\u0006 יהודי \u0005רומא שהיה פתוח לחדר אחד שהיה מונח בו]\u0006 \u0003מת, והוו בעו כהני למיעל לצלויי התם\u0004 \u0005[ורצו הכהנים להכנס להתפלל שם]\u0006 ולא יכלו משום טומאת המת, שכיון שהיה חדר המת פתוח לבית הכנסת, הרי הטומאה בכל החלל. \u0003אתו\u0004 \u0005[באו],\u0006 \u0003אמרו ליה\u0004 \u0005[לו]\u0006 \u0003לרבא\u0004 ושאלו מה יעשו. \u0003אמר להו\u0004 \u0005[להם]:\u0006 \u0003דלו תיבותא אותבוה\u0004 \u0005[הרימו\u0006 את \u0005ארון הקודש\u0006 שהיה מיטלטל בקושי \u0005והניחו אותו\u0006 בפתח\u0005],\u0006 \u0003דהוה ליה\u0004 \u0005[שהרי הוא]\u0006 \u0003כלי עץ עשוי לנחת\u0004 (כלי עץ העשוי להיות מונח במקום קבוע אחד), \u0003ו\u0004כלל הוא, ש\u0003כלי עץ העשוי לנחת, אינו מקבל טומאה\u0004 בעצמו \u0003ו\u0004לכן הוא \u0003חוצץ בפני הטומאה.\u0004","\u0003אמרו ליה רבנן\u0004 \u0005[לו חכמים]\u0006 \u0003לרבא: והא זמנין דמטלטלי ליה כי מנח\u0004 \u0005[הרי לפעמים מטלטלים אותו,\u0006 את הארון, גם \u0005כאשר מונח]\u0006 \u0003ספר תורה עלויה\u0004 \u0005[עליו]\u0006 \u0003והוה ליה מיטלטלא\u0004 \u0005[והרי הוא\u0006 איפוא \u0005מיטלטל]\u0006 \u0003מלא וריקם,\u0004 וכלי שהוא מיטלטל גם בהיותו ריק וגם בהיותו מלא אינו נחשב כעשוי לנחת אלא ככלי מיטלטל והריהו מקבל טומאה ואינו חוצץ בפניה. אמר להם: \u0003אי הכי\u0004 \u0005[אם כך]\u0006 \u0003לא אפשר,\u0004 אי אפשר לעשות תיקון בכך.","\u0003אמר מר זוטרא: מטפחות\u0004 שעוטפים בהן \u0003ספרים\u0004 (ספרי תורה) \u0003שבלו\u0004 — \u0003עושים אותם תכריכים למת מצוה,\u0004 כלומר, מת שאין מי שיטפל בקבורתו והמצוה מוטלת על הכל, \u0003וזו היא גניזתן,\u0004 כלומר, כך גונזים אותם בצורה הראויה ביותר.","\u0003ואמר רבא: ספר תורה שבלה\u0004 — \u0003גונזים\u0004 (קוברים) \u0003אותו אצל\u0004 קברו של \u0003תלמיד חכם, ו\u0004לאו דווקא גדול בתורה, אלא \u0003אפילו שונה הלכות\u0004 בלבד, שהיה בקי במשניות ובברייתא די בכך. \u0003אמר רב אחא בר יעקב: ו\u0004גונזים את הספר \u0003בכלי חרס, שנאמר: \"ונתתם בכלי חרס למען יעמדו ימים רבים\"\u0004 (ירמיה לב, יד).","\u0003אמר רב פפי משמיה\u0004 \u0005[משמו]\u0006 של \u0003רבא:\u0004 להפוך ולעשות \u0003מבי כנישתא לבי רבנן\u0004 \u0005[מבית כנסת לבית חכמים,\u0006 בית מדרש\u0005]\u0006 — \u0003שרי\u0004 \u0005[מותר],\u0006 ואולם לעשות \u0003מבי רבנן לבי כנישתא\u0004 \u0005[מבית חכמים לבית כנסת] —\u0006 \u0003אסיר\u0004 \u0005[אסור]\u0006 לשנות. \u0003ורב פפא משמיה\u0004 \u0005[משמו]\u0006 של \u0003רבא מתני איפכא\u0004 \u0005[\u0006היה \u0005שונה להיפך],\u0006 שלדבריו בית הכנסת מקודש מבית מדרש. \u0003אמר רב אחא:\u0004"],["\u0003כוותיה\u0004 \u0005[כשיטתו]\u0006 של \u0003רב פפי מסתברא\u0004 \u0005[מסתבר]\u0006 לומר, ש\u0003אמר ר' יהושע בן לוי: בית הכנסת מותר לעשותו בית המדרש.\u0004 ומסכמים: אכן \u0003שמע מינה\u0004 \u0005[למד מכאן]\u0006 שכן הוא.","\u0003דרש בר קפרא: מאי דכתיב\u0004 \u0005[מהו שנאמר]:\u0006 \u0003\"וישרף את בית ה' ואת בית המלך ואת כל בתי ירושלים ואת כל בית גדול שרף באש\"\u0004 (מלכים ב' כה, ט), והוא מפרש: \u0003\"בית ה'\" — זה בית המקדש. \"בית המלך\" — אלו פלטרין\u0004 (ארמונות) \u0003של מלך. \"ואת כל בתי ירושלים\" — כמשמען. \"ואת כל בית גדול שרף באש\"\u0004 — נחלקו בכך \u0003ר' יוחנן ור' יהושע בן לוי, חד\u0004 \u0005[אחד\u0006 מהם\u0005]\u0006 \u0003אמר: מקום שמגדלים בו תורה, וחד\u0004 \u0005[אחד\u0006 מהם\u0005]\u0006 \u0003אמר: מקום שמגדלים בו תפלה.\u0004","ומפרשים את דבריהם: \u0003מאן דאמר\u0004 \u0005[מי שאומר]\u0006 שהוא מקום שמגדלים בו \u0003תורה,\u0004 הסתמך על מה \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"ה' חפץ למען צדקו יגדיל תורה ויאדיר\"\u0004 (ישעיהו מב, כא), משמע שתורה היא הנקראת דבר גדול. \u0003ומאן דאמר\u0004 \u0005[ומי שאומר]\u0006 שהוא מקום שמגדלים בו \u0003תפלה,\u0004 הסתמך על מה \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"ספרה נא\u0004 לי את כל \u0003הגדלות אשר עשה אלישע\"\u0004 (מלכים ב' ח, ד), \u0003ואלישע\u0004 מה \u0003דעבד\u0004 \u0005[שעשה] —\u0006 \u0003ברחמי הוא דעבד\u0004 \u0005[ב\u0006בקשת \u0005רחמים,\u0006 בתפילה \u0005הוא שעשה],\u0006 משמע שתפילה היא הגדולה.","ומעירים: \u0003תסתיים\u0004 \u0005[תתפרש]\u0006 המחלוקת ויתבהרו דעות החולקים ש\u0003ר' יהושע בן לוי הוא\u0004 ש\u0003אמר מקום שמגדלים בו תורה,\u0004 והראיה ממה ש\u0003אמר ר' יהושע בן לוי\u0004 במקום אחר: \u0003בית הכנסת מותר לעשותו בית המדרש,\u0004 ומכאן שלדעתו בית המדרש גדול בקדושתו מבית הכנסת. ומסכמים: אכן, \u0003שמע מינה\u0004 \u0005[למד מכאן]\u0006 שזו שיטתו, שתורה גדולה מתפילה.","שנינו במשנה: \u0003אבל מכרו תורה\u0004 — \u0003לא יקחו ספרים וכו'. איבעיא להו\u0004 \u0005[נשאלה להם]\u0006 ללומדים שאלה זו: \u0003מהו למכור ספר תורה ישן\u0004 על מנת \u0003ליקח\u0004 (לקנות) \u0003בו חדש?\u0004 וצדדי השאלה: \u0003כיון דלא מעלי ליה\u0004 \u0005[שאינו מעלה אותו\u0006 בקדושה\u0005]\u0006 \u0003אסור, או דלמא\u0004 \u0005[שמא]\u0006 \u0003כיון דליכא לעלויי עילוייא אחרינא, שפיר דמי\u0004 \u0005[שאין עילוי אחר,\u0006 שהרי הוא מקודש מהכל, \u0005ראוי הדבר\u0006 ומותר\u0005]?\u0006","ומציעים: \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 פתרון לשאלה ממה ששנינו במשנתנו: \u0003אבל מכרו תורה לא יקחו ספרים\u0004 (נביאים וכתובים). ונדייק: \u0003ספרים הוא\u0004 ש\u0003לא\u0004 יקחו, \u0003הא\u0004 \u0005[הרי]\u0006 \u0003תורה בתורה שפיר דמי\u0004 \u0005[ראוי הדבר].\u0006 ודוחים: \u0003מתניתין\u0004 \u0005[המשנה שלנו]\u0006 היא במקרה של \u0003דיעבד\u0004 שכבר מכרו את הספר, \u0003כי קא מיבעיא לן\u0004 \u0005[כאשר נשאלה לנו\u0006 השאלה\u0005],\u0006 היתה זו אם להתיר לעשות כן \u0003לכתחלה.\u0004","\u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ראיה אחרת ממה ששנינו: \u0003גוללים\u0004 (עוטפים) \u0003ספר תורה במטפחות חומשין, ו\u0004גוללים \u0003חומשין במטפחות נביאים וכתובים,\u0004 כיון שבכל אלה הריהו מעלה את המטפחות לקדושה גדולה יותר, \u0003אבל לא\u0004 גוללים \u0003נביאים וכתובים במטפחות חומשים, ולא חומשים במטפחות ספר תורה,\u0004 כיון שבכך הריהו מוריד אותם לקדושה נמוכה יותר.","\u0003קתני מיהת\u0004 \u0005[שנינו על כל פנים]\u0006 ש\u0003גוללים ספר תורה במטפחות חומשים,\u0004 ונדייק ב\u0003מטפחות חומשים — אין\u0004 \u0005[כן]\u0006 מותר, אבל ב\u0003מטפחות\u0004 של \u0003ספר תורה\u0004 אחר — \u0003לא,\u0004 משמע שאין לשנות מספר תורה אחד לחבירו.","ודוחים: \u0003אימא סיפא\u0004 \u0005[אמור\u0006 את \u0005סופה]\u0006 של אותה ברייתא: \u0003ולא חומשים במטפחות ספר תורה,\u0004 ונדייק מכאן: \u0003הא\u0004 \u0005[הרי]\u0006 \u0003תורה בתורה שפיר דמי\u0004 \u0005[ראוי הדבר]!\u0006 ואם כן יש לכאורה סתירה פנימית בברייתא זו, \u0003אלא\u0004 חייבים אנו לאמר על הוכחה זו כי \u0003מהא ליכא למישמע מינה\u0004 \u0005[מ\u0006ברייתא \u0005זו אין לשמוע ממנה]\u0006 בדרך של דיוק, מן החיוב לשלילה.","ומציעים עוד: \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ממה ששנינו בתוספתא: \u0003מניחים ספר תורה על גבי\u0004 ספר \u0003תורה\u0004 אחר, \u0003ותורה על גבי חומשים, וחומשים על גבי נביאים וכתובים, אבל לא\u0004 יניחו \u0003נביאים וכתובים על גבי חומשים, ולא חומשים על גבי תורה.\u0004 משמע שספר תורה אחד יכול להשתמש בספר אחר, ובודאי שמותר אם כן להשתמש במטפחתו.","ודוחים: \u0003הנחה קאמרת\u0004 \u0005[אתה אומר],\u0006 \u0003שאני\u0004 \u0005[שונה]\u0006 \u0003הנחה\u0004 ש\u0003לא אפשר\u0004 אחרת, שבהכרח יש להניחם זה על זה בארון הקודש. \u0003דאי\u0004 \u0005[שאם]\u0006 \u0003לא תימא הכי\u0004 \u0005[תאמר כך]\u0006 שבמקום שאי אפשר חייבים להניח זה על זה, אם כן \u0003מיכרך היכי כרכינן\u0004 \u0005[לכרוך\u0006 את ספר התורה סביב עצמו \u0005כיצד כורכים אנו]\u0006 \u0003והא קא יתיב דפא אחבריה\u0004 \u0005[והרי יושב,\u0006 מונח, \u0005דף\u0006 אחד \u0005על חבירו]!\u0006 \u0003אלא כיון דלא\u0004 \u0005[שאי]\u0006 \u0003אפשר\u0004 לעשות אחרת — \u0003שרי\u0004 \u0005[מותר],\u0006 \u0003הכא נמי\u0004 \u0005[כאן גם כן]\u0006 \u0003כיון\u0004 ש\u0003לא אפשר\u0004 להניחם בארון הקודש בדרך אחרת — \u0003שרי\u0004 \u0005[מותר].\u0006","ומציעים, \u0003תא שמע\u0004 \u0005[בא\u0006 ו\u0005שמע]\u0006 ראיה ממה ש\u0003אמר רבה בר בר חנה אמר ר' יוחנן משום\u0004 \u0005[בשם]\u0006 \u0003רבן שמעון בן גמליאל: לא ימכור אדם ספר תורה ישן\u0004 כדי \u0003ליקח\u0004 (לקנות) \u0003בו חדש.\u0004","ודוחים: משם אין ראיה, \u0003התם\u0004 \u0005[שם]\u0006 \u0003משום פשיעותא\u0004 \u0005[\u0006חשש \u0005לרשלנות]\u0006 שימכור את הישן ולבסוף לא יקנה חדש, ואולם \u0003כי קאמרינן\u0004 \u0005[כאשר אומרים,\u0006 שואלים \u0005אנו]\u0006 הרי זה \u0003כגון דכתיב ומנח לאיפרוקי\u0004 \u0005[ש\u0006הספר החדש היה כבר \u0005כתוב ומונח להפדות,\u0006 להמכר\u0005],\u0006 \u0003מאי\u0004 \u0005[מה\u0006 דינו\u0005]?\u0006","ומביאים ראיה, \u0003תא שמע\u0004 \u0005[בא\u0006 ו\u0005שמע]:\u0006 ש\u0003אמר ר' יוחנן משום\u0004 \u0005[בשם]\u0006 \u0003ר' מאיר: אין מוכרים ספר תורה אלא\u0004 אם אדם נזקק לכסף כדי \u0003ללמוד תורה\u0004 או \u0003לישא אשה.\u0004","\u0003שמע מינה\u0004 \u0005[למד מכאן]\u0006 כי \u0003תורה בתורה שפיר דמי\u0004 \u0005[ראוי הדבר],\u0006 שהרי מוכר ספר תורה לשם תורה. ודוחים: \u0003דלמא שאני\u0004 \u0005[שמא שונה]\u0006 \u0003למוד, שהלמוד מביא לידי מעשה,\u0004 ולכן חשוב ביותר ועדיף על ספר תורה. \u0003אשה נמי\u0004 \u0005[גם כן]\u0006 יש ענין חשוב בנישואין, שהרי נאמר: \u0003\"לא תהו בראה לשבת יצרה\"\u0004 (ישעיהו מה, יח), משמע שלכך נוצר העולם, \u0003אבל תורה בתורה לא\u0004 יחליף.","באותו ענין \u0003תנו רבנן\u0004 \u0005[שנו חכמים\u0006 בברייתא\u0005]:\u0006 \u0003לא ימכור אדם ספר תורה אף על פי שאינו צריך לו. יתר על כן אמר רבן שמעון בן גמליאל: אפילו אין לו מה יאכל ומכר ספר תורה או\u0004 מכר את \u0003בתו\u0004 לאמה — \u0003אינו רואה סימן ברכה לעולם,\u0004 משמע שאין זה מן הראוי למכור ספר תורה אפילו מפני ההכרח.","שנינו במשנה \u0003וכן\u0004 הדין \u0003במותריהן. אמר רבא: לא שנו\u0004 שיש קדושה זו במותרי דברים מקודשים, \u0003אלא שמכרו\u0004 דבר שיש בו קדושה וקנו בדמיו דבר שקדושתו גדולה מזו \u0003והותירו\u0004 מכסף המכירה, \u0003אבל\u0004 אם \u0003גבו\u0004 כסף מן הציבור כדי לקנות בו דבר זה \u0003ו\u0004לאחר שקנו \u0003הותירו — מותר\u0004 להשתמש במותר לכל צורך אחר. שעדיין לא נתפסו הדמים בקדושה.","\u0003איתיביה\u0004 \u0005[הקשה לו]\u0006 \u0003אביי\u0004 מברייתא: \u0003במה דברים אמורים\u0004 שאסור לשנות כספים של חפצי קודש — כ\u0003שלא התנו\u0004 במפורש שיוכלו לעשות בכסף כרצונם, \u0003אבל\u0004 אם \u0003התנו — אפילו לדוכסוסיא מותר.\u0004","ומעתה נברר: \u0003היכי דמי\u0004 \u0005[כיצד בדיוק\u0006 היה הדבר\u0005]?\u0006 \u0003אילימא\u0004 \u0005[אם תאמר]\u0006 \u0003שמכרו והותירו — כי\u0004 \u0005[כאשר]\u0006 \u0003התנו מאי הוי\u0004 \u0005[מה יש],\u0006 כיצד רשאים הם להתנות להוריד דבר מקדושתו? \u0003אלא\u0004 ודאי מדובר \u0003שגבו והותירו,\u0004 וגם אז \u0003טעמא\u0004 \u0005[הטעם,\u0006 דווקא\u0005]\u0006 ש\u0003התנו, הא\u0004 \u0005[הרי]\u0006 אם \u0003לא התנו — לא!\u0004","ודוחה רבא: \u0003לעולם\u0004 תפרש \u0003שמכרו והותירו, והכי קאמר\u0004 \u0005[וכך אמר,\u0006 כך יש להבין\u0005]:\u0006 \u0003במה דברים אמורים — כ\u0004\u0003שלא התנו שבעה טובי העיר במעמד אנשי העיר\u0004 על דבר זה, \u0003אבל התנו שבעה טובי העיר במעמד אנשי העיר\u0004 שתפקע הקדושה מהדמים, \u0003אפילו לדוכסוסיא נמי\u0004 \u0005[גם כן]\u0006 \u0003מותר.\u0004","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי לההוא מרבנן דהוה מסדר מתניתא קמיה\u0004 \u0005[לאחד החכמים שהיה מסדר משניות לפני]\u0006 \u0003רב ששת: מי שמיע לך\u0004 \u0005[האם שמעת]\u0006 \u0003מרב ששת מאי\u0004 \u0005[מה]\u0006 פירוש המלה \u0003\"דוכסוסיא\"\u0004 הנזכרת בברייתא שהבאנו? \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003הכי\u0004 \u0005[כך]\u0006 \u0003אמר רב ששת: פרשא דמתא\u0004 \u0005[הפרש של העיר]\u0006 שבני העיר משתמשים בשירותיו לשמירה ולשליחויות ציבוריות.","\u0003אמר אביי: הלכך\u0004 \u0005[על כן]\u0006 אפשר ללמוד ממעשה זה, \u0003האי צורבא מרבנן דשמע ליה מילתא\u0004 \u0005[תלמיד חכם ששמע דבר]\u0006 \u0003ולא ידע פירושא\u0004 \u0005[ואינו יודע\u0006 את \u0005פירושו]\u0006 \u0003לישיילה קמיה דשכיח קמיה רבנן\u0004 \u0005[שישאל\u0006 את הדבר \u0005למי שמצוי לפני החכמים],\u0006 \u0003דלא אפשר דלא שמיע ליה מן גברא רבה\u0004 \u0005[שאי אפשר שלא שמע את\u0006 פירוש הדבר \u0005מאדם גדול].\u0006","\u0003אמר ר' יוחנן משום ר' מאיר: בני העיר שהלכו\u0004 יחד \u0003לעיר אחרת\u0004 (כגון לאסיפת ציבור או בתענית) \u0003ופסקו עליהם צדקה,\u0004 כלומר, עשו שם מגבית וגם האורחים נדבו סכום מסויים לצדקה — \u0003נותנין\u0004 את הכסף שנדבו, לגבאי אותה עיר, כדי שלא יחשדו בהם שאינם נותנים את נדריהם, אבל \u0003כשהן באין\u0004 למקומם \u0003מביאים אותה,\u0004 שמקבלים בחזרה את כספי צדקה שפסקו, \u0003ומפרנסין בה עניי עירן,\u0004 ואין נותנים את הכסף לעיר שהיו בה.","ומעירים, \u0003תניא נמי הכי\u0004 \u0005[שנויה\u0006 ברייתא \u0005גם כן כך]:\u0006 \u0003בני העיר שהלכו לעיר אחרת ופסקו עליהם צדקה — נותנין, וכשהם באים — מביאים אותה עמהן, ויחיד שהלך לעיר אחרת ופסקו עליו צדקה — תנתן לעניי אותה העיר\u0004 שנדב בה צדקה, ואינו רשאי לקחת את הכסף כדי לתיתו לעניי עירו.","מסופר: \u0003רב הונא גזר תעניתא\u0004 \u0005[תענית],\u0006 \u0003על לגביה\u0004 \u0005[\u0006ו\u0005באו אליו]\u0006 בין השאר \u0003רב חנה בר חנילאי וכל בני מתיה\u0004 \u0005[עירו],\u0006 \u0003רמו עלייהו\u0004 \u0005[הטילו עליהם]\u0006 ליתן \u0003צדקה ויהבו\u0004 \u0005[ו\u0006הם \u0005נתנו].\u0006 \u0003כי בעו למיתי\u0004 \u0005[כאשר רצו לחזור למקומם]\u0006 \u0003אמרו ליה\u0004 \u0005[לו]\u0006 לרב הונא: \u0003נותבה לן מר וניזול\u0004 \u0005[יתן לנו אדוני אותה,\u0006 את הצדקה שנתנו, \u0005ונלך]\u0006 \u0003ונפרנס בה\u0004 את \u0003עניי מאתין\u0004 \u0005[עירנו].\u0006","\u0003אמר להו\u0004 \u0005[להם]:\u0006 \u0003תנינא\u0004 \u0005[שנינו]\u0006 על כך: \u0003במה דברים אמורים\u0004 שצדקה זו של בני העיר ניתנת לעירם — \u0003בשאין שם\u0004 בעיר שבה פסקו את הצדקה"],["\u0003חבר עיר\u0004 תלמיד חכם הממונה על צרכי העיר, \u0003אבל\u0004 אם \u0003יש שם חבר עיר — תנתן\u0004 הצדקה \u0003לחבר עיר\u0004 והוא יטפל בענין. \u0003וכל שכן\u0004 במקרה שלנו \u0003דעניי דידי ודידכו עלי סמיכי\u0004 \u0005[שהעניים שלי ושלכם עלי\u0006 הם \u0005נשענים],\u0006 שהוא היה ממונה גם על מתן הצדקה במקומות הסמוכים, ובודאי שראוי להפקיד בידו את הכסף כדי שיחלק אותו לכולם.","\u0003אין מוכרים את\u0004 כל דבר שבקדושה, שהוא \u0003של רבים, ליחיד,\u0004 אף שהוא משמש בו לאותו שימוש, \u0003מפני שמורידים אותו מקדושתו\u0004 שקודם היה לקדושת רבים ועכשיו הוא רק ליחיד, אלו \u0003דברי ר' מאיר. אמרו לו: אם כן\u0004 לפי אותו טעם \u0003אף לא\u0004 ימכרו דבר שבקדושה שהוא של \u0003עיר גדולה לעיר קטנה,\u0004 שגם אז ממעטים בציבור.","ושואלים: \u0003שפיר קאמרי ליה רבנן\u0004 \u0005[יפה אמרו לו חכמים]\u0006 \u0003לר' מאיר,\u0004 שלכאורה הוכחה טובה היא, ומה עונה ר' מאיר על כך? \u0003ו\u0004משיבים: \u0003ר' מאיר\u0004 סבור שבמכירה \u0003מעיר גדולה לעיר קטנה\u0004 אין שינוי מהותי — כי \u0003מעיקרא קדישא, השתא נמי קדישא\u0004 \u0005[מתחילה\u0006 היתה \u0005קדושה\u0006 לרבים \u0005ועכשיו\u0006 היא \u0005גם כן קדושה\u0006 לרבים\u0005],\u0006 שהרי אף מכירה לעיר קטנה היא מכירה לציבור, אולם במכירה \u0003מרבים ליחיד\u0004 הלא בסופו של דבר אחרי המכירה \u0003ליכא\u0004 \u0005[אין]\u0006 את אותה \u0003קדושה\u0004 שהיתה בו קודם, שהרי מקודם היה של ציבור ועתה הוא של יחיד.","\u0003ורבנן\u0004 \u0005[וחכמים]\u0006 מה משיבים הם על נימוק זה — לדעתם \u0003אי איכא למיחש\u0004 \u0005[אם יש\u0006 מקום \u0005לחשוש]\u0006 להורדה בכבוד, אם כן \u0003כי האי גוונא נמי איכא למיחש\u0004 \u0005[כגון זה גם כן יש מקום לחשוש],\u0006 שהרי כלל הוא \u0003\"ברב עם הדרת מלך\"\u0004 (משלי יד, כח) ואם איננו חוששים להשאיר את הדבר ברוב עם, אף אין צריכים לחשוש בנתינה ליחיד.","\u0003אין מוכרים בית כנסת אלא על תנאי, שאם ירצו\u0004 בני הקהילה אחר כך \u0003יחזירוהו\u0004 להם, אלו \u0003דברי ר' מאיר. וחכמים אומרים: מוכרים אותו\u0004 את בית הכנסת \u0003ממכר עולם\u0004 לכל צורך שהוא, \u0003חוץ מ\u0004ל\u0003ארבעה דברים\u0004 שיש בהם משום בזיון, והם: \u0003למרחץ\u0004 שיש בו אנשים ערומים, \u0003ולבורסקי\u0004 (מקום עיבוד עורות), מפני שריחם רע, \u0003לטבילה\u0004 מאותו טעם של מרחץ, \u0003ולבית המים\u0004 (לבית הכיסא). \u0003ר' יהודה אומר: מוכרים אותה\u0004 את בית הכנסת \u0003לשם חצר\u0004 בלא לפרש לאיזו מטרה, \u0003והלוקח — מה שירצה יעשה.\u0004","ושואלים: \u0003ול\u0004שיטת \u0003ר' מאיר, היכי דיירי בה\u0004 \u0005[איך דרים\u0006 אנשים \u0005בו]\u0006 בבית הכנסת לאחר שמכרוהו? \u0003הא הויא לה\u0004 \u0005[הרי זו]\u0006 \u0003רבית,\u0004 שהרי נמכר על מנת להחזירו, ולכשיחזירוהו יקבלו את כל מחירו, ונמצא שהדיירים שדרו ונהנו מהדירה במשך הזמן, הרי הם כאילו הלוו כסף לבית הכנסת וקיבלו עליו ריבית!","\u0003אמר ר' יוחנן: ר' מאיר בשיטת ר' יהודה אמרה,\u0004 ש\u0003אמר\u0004 רבי יהודה: \u0003צד אחד ברבית מותר.\u0004 כלומר, ריבית שאיננה מובטחת מראש, אלא עלולה לבוא מתוך שתתבטל העיסקה — הריהי מותרת.","\u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003הרי שהיה נושה בחבירו מנה\u0004 ולא היה לחבר מנה לשלם, \u0003ועשה לו שדהו מכר\u0004 כלומר, הלווה מכר למלוה את השדה כתשלום, ואם לאחר מכן ימצא הלווה כסף יחזיר לו המלווה את השדה — \u0003בזמן שמוכר אוכל פירות,\u0004 אם המוכר־הלווה עדיין אוכל את פירות השדה עד שהוא מחזיר לו את הכסף — בודאי \u0003מותר,\u0004 אבל אם ה\u0003לוקח\u0004 (המלוה) הוא ש\u0003אוכל פירות\u0004 בינתיים — \u0003אסור,\u0004 שהרי זו ריבית שהוא מקבל על ההשהיה בפרעון הכסף.","\u0003ר' יהודה אומר: אפילו לוקח אוכל פירות — מותר,\u0004 שהרי יתכן שלא ימצא המוכר כסף ונמצא שהשדה היה של הקונה־המלוה מזמן מכירתו, ואין כאן ריבית. \u0003ואמר ר' יהודה\u0004 ראיה לדבריו: \u0003מעשה בביתוס בן זונן שעשה שדהו מכר על פי\u0004 הדרכת \u0003ר' אלעזר בן עזריה, ולוקח אוכל פירות היה. אמרו לו: משם\u0004 אתה מביא \u0003ראיה?!\u0004 שם שלא כדבריך, ה\u0003מוכר אוכל פירות היה ולא לוקח.\u0004","והסברנו: \u0003מאי בינייהו\u0004 \u0005[מה\u0006 ההבדל \u0005ביניהם]\u0006 בין שיטת חכמים לשיטת ר' יהודה? \u0003צד אחד ברבית איכא בינייהו\u0004 \u0005[יש ביניהם].\u0006 \u0003מר סבר\u0004 \u0005[חכם זה,\u0006 ר' יהודה \u0005סבור]\u0006 כי \u0003צד אחד ברבית מותר, ומר סבר\u0004 \u0005[וחכם זה,\u0006 חכמים \u0005סבורים]:\u0006 \u0003צד אחד ברבית אסור.\u0004","\u0003רבא אמר: דכולי עלמא\u0004 \u0005[לדעת הכל]\u0006 \u0003צד אחד ברבית אסור,\u0004 אלא \u0003והכא\u0004 \u0005[וכאן]\u0006 בענין \u0003רבית על מנת להחזיר איכא בינייהו\u0004 \u0005[יש ביניהם]\u0006 הבדל למעשה, שההסכם היה שאם יקבל המלוה את כספו, יחזיר המלוה־הלוקח גם את הקרקע וגם את דמי הפירות שאכל, ש\u0003מר סבר\u0004 \u0005[חכם זה\u0006 ר' יהודה \u0005סבור]:\u0006 \u0003רבית על מנת להחזיר — מותר, ומר סבר\u0004 \u0005[וחכם זה,\u0006 חכמים, \u0005סבור]\u0006 \u0003אסור.\u0004 ולשיטה זו, גם בבית הכנסת שנמכר התנו שאם יחזירוהו ישלמו הדיירים שכר דירה.","שנינו במשנה: \u0003וחכמים אומרים מוכרים אותו ממכר עולם וכו'.\u0004 בקשר למחלוקת זו מביאים, \u0003אמר רב יהודה אמר שמואל: מותר לאדם להשתין מים בתוך ארבע אמות של תפלה,\u0004 כלומר, לאחר שמתפלל יכול להטיל מים אף באותו מקום.","\u0003אמר רב יוסף: מאי קא משמע לן\u0004 \u0005[מה השמיע לנו]\u0006 בכך? \u0003תנינא\u0004 \u0005[שנינו]\u0006 כך במשנה, \u0003ר' יהודה אומר: מוכרים אותה\u0004 את בית הכנסת \u0003לשום חצר, ולוקח מה שירצה יעשה,\u0004 משמע, אפילו לשמש בית הכיסא. \u0003ואפילו רבנן\u0004 \u0005[חכמים]\u0006 \u0003לא קאמרי\u0004 \u0005[אמרו]\u0006 שאסור, \u0003אלא\u0004 לגבי \u0003בית הכנסת דקביע קדושתיה\u0004 \u0005[שקבועה קדושתו],\u0006 \u0003אבל ארבע אמות\u0004 שהתפלל בהן באופן מזדמן \u0003דלא קביע קדושתייהו\u0004 \u0005[שאין קדושתן קבועה],\u0006 בודאי \u0003לא\u0004 אסרו בכך.","\u0003תני תנא קמיה\u0004 \u0005[שנה השונה,\u0006 חוזר המשניות \u0005לפני]\u0006 \u0003רב נחמן\u0004 ברייתא זו: \u0003המתפלל\u0004 — \u0003מרחיק ארבע אמות\u0004 ממקום תפילתו \u0003ומשתין, והמשתין\u0004 — \u0003מרחיק ארבע אמות ומתפלל.\u0004","\u0003אמר ליה\u0004 \u0005[לו]\u0006 רב נחמן: \u0003בשלמא\u0004 \u0005[נניח]\u0006 מה שאמרת שה\u0003משתין מרחיק ארבע אמות ומתפלל\u0004 — דבר זה \u0003תנינא\u0004 \u0005[שנינו]\u0006 כבר במקום אחר, ששנינו: \u0003כמה ירחיק מהם\u0004 ממי הרגלים \u0003ומהצואה — ארבע אמות\u0004 כדי שלא יתפלל במקום מאוס.","\u0003אלא המתפלל מרחיק ארבע אמות ומשתין למה לי? אי הכי\u0004 \u0005[אם כך]\u0006 שאתה אומר שארבע אמות מתקדשות בתפילה, הרי לפי זה \u0003קדשתינהו לכולהו\u0004 \u0005[קדשת את כל]\u0006 \u0003שבילי\u0004 העיר \u0003נהרדעא,\u0004 שבודאי התפללו אנשים בכל שביל בה. אלא \u0003תני\u0004 \u0005[שנה]:\u0006 \u0003ישהה\u0004 במקום לאחר התפילה כשיעור מהלך ארבע אמות ולא יעשה זאת מיד.","ושואלים: \u0003בשלמא\u0004 \u0005[נניח]\u0006 שה\u0003משתין ישהה כדי הילוך ארבע אמות\u0004 ואחר כך יתפלל, הסיבה לכך היא \u0003משום ניצוצות\u0004 (טיפות קטנות) של מי רגלים שאולי עדיין נוטפות ממנו, ויחכה עד שיפסקו, \u0003אלא\u0004 ה\u0003מתפלל ישהה כדי הילוך ארבע אמות, למה לי? אמר רב אשי: שכל\u0004 כדי הילוך \u0003ארבע אמות\u0004 עדיין \u0003תפלתו סדורה בפיו ורחושי מרחשן שפוותיה\u0004 \u0005[ושפתותיו עדיין מרחשות\u0006 תפילה\u0005]\u0006 ולכן צריך שיעשה הפסקה מסויימת.","אגב הלכה זו מביאים כמה דברים על מעשי חכמים. ו\u0003זלפ\"ן\u0004 הוא ה\u0003סימן\u0004 להם \u0003(\u0004= \u0003ז\u0004כאי, א\u0003ל\u0004עזר, \u0003פ\u0004רידא, \u0003נ\u0004חוניא).","\u0003שאלו תלמידיו את ר' זכאי: במה\u0004 זכית ש\u0003הארכת ימים? אמר להם: מימי לא השתנתי מים בתוך ארבע אמות של תפלה, ולא כניתי שם לחבירי, ולא ביטלתי קידוש היום\u0004 (של שבת) על יין. \u0003אמא זקנה היתה לי, פעם אחת מכרה כפה שבראשה\u0004 שהיו נוהגות הנשים ללבוש על השיער מתחת לכיסוי הראש \u0003והביאה לי\u0004 במחירה יין ל\u0003קידוש היום,\u0004 עד כדי כך הקפדתי במצוה זו.","ומעירים: \u0003תנא\u0004 \u0005[שנה]\u0006 החכם: \u0003כשמתה\u0004 אמו \u0003הניחה לו שלש מאות גרבי\u0004 (כדי) \u0003יין,\u0004 שבזכות מצוה זו זכתה והתעשרה והיה לה יין רב. \u0003כשמת הוא, הניח לבניו שלשת אלפים גרבי יין.\u0004","מסופר: \u0003רב הונא הוה אסר ריתא וקאי קמיה\u0004 \u0005[היה חגור בקש ועומד לפני]\u0006 \u0003רב, אמר ליה\u0004 \u0005[לו]\u0006 רב: \u0003מאי האי\u0004 \u0005[מה זה]?\u0006 מדוע לבוש אתה כך? \u0003אמר\u0004 לו: \u0003לא הוה\u0004 \u0005[היה]\u0006 \u0003לי\u0004 יין \u0003קידושא, ומשכנתיה להמיינאי ואתאי ביה קידושא\u0004 \u0005[\u0006ל\u0005קידוש, ומישכנתי את חגורתי והבאתי בה,\u0006 במחירה, יין ל\u0005קידוש].\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 רב: \u0003יהא רעוא דתיטום בשיראי\u0004 \u0005[יהי רצון ש\u0006בזכות מצוה זו \u0005תהיה טמון\u0006 ומכוסה \u0005בתוך משי].\u0006","ומספרים: \u0003כי איכלל\u0004 \u0005[כאשר התחתן]\u0006 \u0003רבא בריה\u0004 \u0005[בנו]\u0006 של רב הונא, \u0003רב הונא איניש גוצא הוה, גנא אפוריא\u0004 \u0005[אדם נמוך היה\u0006 ו\u0005שוכב\u0006 היה \u0005על מיטה],\u0006 וכיון שהיה נמוך לא שמו לב שהוא שוכב במיטה. \u0003אתיין בנתיה וכלתיה שלחן ושדיין מנייהו עליה עד דאיטום בשיראי\u0004 \u0005[באו בנותיו וכלותיו פשטו\u0006 את \u0005בגדיהן והשליכו עליו עד שהתכסה כולו במשי]\u0006 שזכה לעושר, ונתקיימה בו ברכתו של רב כלשונה. ומספרים: כש\u0003שמע רב\u0004 על כך \u0003איקפד\u0004 \u0005[הקפיד]\u0006 על רב הונא, ו\u0003אמר: מאי טעמא\u0004 \u0005[מה טעם]\u0006 \u0003לא אמרת לי כי\u0004 \u0005[כאשר]\u0006 \u0003ברכתיך: \"וכן למר\u0004 \u0005[לאדוני]\u0006\u0003\",\u0004 שאם היית אומר כן היה מתקיים גם בי דבר זה?","עוד מסופר: \u0003שאלו תלמידיו של ר' אלעזר בן שמוע: במה,\u0004 באיזו זכות \u0003הארכת ימים? אמר להם: מימי לא עשיתי קפנדריא\u0004 (קיצור דרך) \u0003לבית הכנסת,\u0004 כלומר, לא עברתי בבית הכנסת כדי לקצר בו את הדרך, \u0003ולא פסעתי על ראשי עם קדוש,\u0004 כלומר, לא הלכתי למקומי בראש בית המדרש בין האנשים היושבים שם על הארץ, שלא להיראות כמהלך על ראשיהם, \u0003ולא נשאתי כפי\u0004 לברכת כהנים \u0003בלא ברכה\u0004 לפני כן.","כיוצא בו \u0003שאלו תלמידיו את ר' פרידא: במה הארכת ימים? אמר להם: מימי לא קדמני אדם לבית המדרש,\u0004 אלא אני הייתי תמיד הראשון."],["\u0003ולא ברכתי\u0004 בסעודה \u0003לפני כהן,\u0004 אלא כיבדתי את הכהן שיהיה בראש, \u0003ולא אכלתי מבהמה שלא הורמו מתנותיה\u0004 (מתנות כהונה: זרוע לחיים וקיבה),","וכפי ש\u0003אמר ר' יצחק אמר ר' יוחנן: אסור לאכול מבהמה שלא הורמו מתנותיה. ואמר ר' יצחק: כל האוכל מבהמה שלא הורמו מתנותיה, כאילו אוכל טבלים\u0004 (תבואה שלא הופרשו ממנה מעשרות), שיש בכך איסור חמור. ומעירים: \u0003ולית הלכתא כוותיה\u0004 \u0005[ואין הלכה כמותו],\u0006 אלא מותר לאכול מבהמה זו, ובכל זאת הקפיד ר' פרידא על עצמו ולא אכל.","ושואלים: ומה שאמר \u0003ולא ברכתי לפני כהן,\u0004","\u0003למימרא דמעליותא היא\u0004 \u0005[האם לומר ש\u0006דבר של \u0005שבח הוא]?\u0006 \u0003והא\u0004 \u0005[והרי]\u0006 \u0003אמר ר' יוחנן: כל תלמיד חכם שמברך לפניו, אפילו כהן גדול עם הארץ — אותו תלמיד חכם חייב מיתה, שנאמר: \"כל משנאי אהבו מות\"\u0004 (משלי ח, לו) \u0003אל תקרי \"משנאי\" אלא משניאי.\u0004 שאותו תלמיד חכם שמזלזל בכבוד עצמו גורם שיזלזלו בתורה וגורם להשניא את התורה על הבריות. אלא תלמיד חכם צריך להיות ראשון בכל דבר, כדי שיידעו אנשים כמה גדול כבודה של התורה.","ומשיבים: \u0003כי קאמר איהו\u0004 \u0005[כאשר אמר הוא],\u0006 ר' פרידא, אמר זאת \u0003בשוין,\u0004 כלומר, כאשר אף הכהן הוא תלמיד חכם, מפני כבוד הכהונה, הקדים את הכהן שיברך לפניו.","ועוד מסופר: \u0003שאלו תלמידיו את ר' נחוניא בן הקנה: במה,\u0004 באיזו זכות \u0003הארכת ימים? אמר להם: מימי לא נתכבדתי בקלון חברי,\u0004 כלומר, לא עשיתי פעולה שיגיע לי כבוד על ידי קלון חברי, \u0003ולא עלתה על מטתי קללת חברי,\u0004 שדאגתי לפייסו מיד, ולפני שהלכתי לישון ידעתי שאין בלבו טינה עלי, \u0003ו\u0004כן \u0003ותרן בממוני הייתי.\u0004","ומסבירים: מה שאמר \u0003לא נתכבדתי בקלון חברי — כי הא\u0004 \u0005[כמו\u0006 מעשה \u0005זה]\u0006 ש\u0003רב הונא דרי מרא אכתפיה\u0004 \u0005[נשא\u0006 \u0005מעדר על כתיפו]\u0006 כשחזר מעבודתו. \u0003אתא\u0004 \u0005[בא]\u0006 \u0003רב חנא בר חנילאי וקא דרי מיניה\u0004 \u0005[ולקח אותו ממנו]\u0006 מפני כבוד רבו, מתוך כוונה שהוא עצמו ישא את המעדר. \u0003אמר ליה\u0004 \u0005[לו]\u0006 רב הונא: \u0003אי רגילת דדרית במאתיך\u0004 \u0005[אם רגיל אתה לשאת\u0006 מעדר \u0005בעירך] —\u0006 \u0003דרי\u0004 \u0005[שא],\u0006 \u0003ואי\u0004 \u0005[ואם]\u0006 \u0003לא\u0004 — \u0003אתייקורי אנא בזילותא דידך, לא ניחא לי\u0004 \u0005[שאני אתכבד בקלון שלך, אין\u0006 הדבר \u0005נוח לי].\u0006","\u0003ולא עלתה על מטתי קללת חברי — כי הא\u0004 \u0005[כמו זה]\u0006 שמסופר, ש\u0003מר זוטרא, כי הוה סליק לפורייה\u0004 \u0005[כאשר היה עולה למיטתו]\u0006 לישון, \u0003אמר: שרי ליה לכל מאן דצערן\u0004 \u0005[מחול לו לכל מי שציער אותי].\u0006","\u0003וותרן בממוני הייתי\u0004 — כיוצא בו \u0003אמר מר\u0004 \u0005[החכם]:\u0006 \u0003איוב ותרן בממוניה הוה\u0004 \u0005[בממונו היה],\u0006 \u0003שהיה מניח פרוטה\u0004 של עודף \u0003לחנוני מממוניה\u0004 \u0005[מממונו],\u0006 ולא היה עומד על קבלת העודף.","מסופר: \u0003שאל ר' עקיבא את ר' נחוניא הגדול, אמר לו: במה הארכת ימים? אתו גווזי וקא מחו ליה\u0004 \u0005[באו סריסיו,\u0006 משרתיו של ר' נחוניא \u0005והיכו אותו]\u0006 את ר' עקיבא, כאדם השואל שאלות סרק, כאילו תוהה ומתרעם למה הוא זקן כל כך. ברח מהם, \u0003סליק יתיב ארישא דדיקלא\u0004 \u0005[עלה\u0006 ו\u0005ישב על ראש הדקל]\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 לר' נחוניא: \u0003רבי,\u0004 יש לי שאלה, נאמר: \"הכבש אחד\" (במדבר כח, ד), ויש להבין, \u0003אם\u0004 (מאחר) ש\u0003נאמר \"כבש\" למה נאמר\u0004 גם \u0003\"אחד\"?\u0004 שהרי די היה לומר \"כבש\", וכיון ששמע רבי נחוניא שאלה זו שהיא שאלת חכם, \u0003אמר להו\u0004 \u0005[להם]\u0006 למשרתיו: \u0003צורבא מדרבנן\u0004 \u0005[תלמיד חכם]\u0006 \u0003הוא\u0004 זה, \u0003שבקוהו\u0004 \u0005[הניחו לו].\u0006","וענה לו תחילה לשאלתו האחרונה: \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003\"אחד\"\u0004 פירושו: \u0003מיוחד שבעדרו\u0004 שצריך לבחור לקרבן כבש משובח.","ועל השאלה הראשונה במה זכה לאריכות ימים, \u0003אמר לו: מימי לא קבלתי מתנות, ולא עמדתי על מדותי\u0004 להתעקש על דברים שייעשו כרצוני, \u0003וותרן בממוני הייתי.\u0004","ומסבירים: \u0003לא קבלתי מתנות — כי הא\u0004 \u0005[כמו\u0006 מעשה \u0005זה]\u0006 שהיה ב\u0003ר' אלעזר, כי הוו משדרי ליה\u0004 \u0005[כאשר היו שולחים לו]\u0006 \u0003מתנות מבי נשיאה\u0004 \u0005[מבית הנשיא] —\u0006 \u0003לא הוה שקיל\u0004 \u0005[לא היה מקבל],\u0006 \u0003כי הוה מזמני ליה\u0004 \u0005[\u0006ו\u0005כאשר היו מזמינים אותו] —\u0006 \u0003לא הוה אזיל\u0004 \u0005[לא היה הולך],\u0006 \u0003אמר להו\u0004 \u0005[להם]:\u0006 האם \u0003לא ניחא לכו\u0004 \u0005[נוח לכם]\u0006 ש\u0003אחיה? דכתיב\u0004 \u0005[ש\u0006הרי \u0005נאמר]:\u0006 \u0003\"\u0004ו\u0003שונא מתנת יחיה\"\u0004 (משלי טו, כז). לעומת זאת מסופר: \u0003ר' זירא כי הוו משדרי ליה מבי נשיאה\u0004 \u0005[כאשר היו שולחים לו\u0006 מתנות \u0005מבית הנשיא] —\u0006 \u0003לא הוה שקיל\u0004 \u0005[לא היה לוקח],\u0006 \u0003כי הוה מזמני ליה\u0004 \u0005[כאשר היו מזמינים אותו] —\u0006 \u0003אזיל\u0004 \u0005[\u0006היה \u0005הולך].\u0006 \u0003אמר: אתייקורי דמתייקרי בי\u0004 \u0005[מתכבדים\u0006 הם \u0005בי]\u0006 ולא שאני נהנה מהם.","ומה שאמר רבי נחוניא \u0003ולא עמדתי על מדותי\u0004 — ש\u0003אמר רבא: כל המעביר על מדותיו\u0004 ומוותר על מה שקבע לעצמו — \u0003מעבירין ממנו\u0004 מן השמים \u0003כל פשעיו, שנאמר: \"נשא עון ועבר על פשע\"\u0004 (מיכה ז, יח), ודייקו: \u0003למי נושא עון — למי שעובר\u0004 (מוחל ומוותר) \u0003על פשע\u0004 שפשעו אנשים כנגדו.","עוד מסופר: \u0003שאל רבי את ר' יהושע בן קרחה: במה הארכת ימים? אמר לו: קצת בחיי?\u0004 שאם לא כן, מדוע תוהה אתה למה אני זקן כל כך! \u0003אמר לו\u0004 רבי לרבי יהושע בן קרחה: \u0003רבי, תורה היא וללמוד אני צריך\u0004 כדי לדעת כיצד מאריכים ימים. \u0003אמר לו\u0004 ר' יהושע בן קרחה: \u0003מימי לא נסתכלתי בדמות אדם רשע.\u0004 ש\u0003אמר ר' יוחנן: אסור לאדם להסתכל בצלם דמות אדם רשע, שנאמר\u0004 שאמר אלישע ליהורם: \u0003\"לולי פני יהושפט מלך יהודה אני נשא אם אביט אליך ואם אראך\"\u0004 (מלכים ב' ג, יד).","\u0003ר' אלעזר אמר:\u0004 המסתכל ברשע \u0003עיניו כהות, שנאמר: \"ויהי כי זקן יצחק ותכהין עיניו מראת\"\u0004 (בראשית כז, א), והטעם \u0003משום דאסתכל\u0004 \u0005[שהסתכל]\u0006 \u0003בעשו הרשע.\u0004","ושואלים: \u0003והא גרמא ליה\u0004 \u0005[ו\u0006כי \u0005זו גרמה לו\u0006 עיורון\u0005]?\u0006 \u0003והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003ר' יצחק: לעולם אל תהי קללת הדיוט\u0004 אף על פי שאינו אדם חשוב \u0003קלה בעיניך, שהרי אבימלך קלל את שרה, ונתקיים\u0004 הדבר \u0003בזרעה, שנאמר\u0004 שאמר אבימלך לשרה: \u0003\"הנה הוא לך כסות עינים\"\u0004 (בראשית כ, טז), ופירשו: \u0003אל תקרי\u0004 \u0005[תקרא]\u0006 \u0003\"כסות\u0004 עינים \u0003\" אלא\u0004 קרא \u0003\"כסיית עינים\",\u0004 כלומר, רמז בדבריו שיגיע להם עיורון, וכך התקיים ביצחק, והרי שהסיבה לעיוורונו היתה הקללה ולא מה שהסתכל בפני עשיו!","ומשיבים: \u0003הא והא גרמא ליה\u0004 \u0005[זו וזו גרמו לו].\u0006 \u0003רבא אמר\u0004 הוכחה לאיסור זה: \u0003מהכא\u0004 \u0005[מכאן]\u0006 יש ללמוד זאת, ממה שנאמר: \u0003\"שאת פני רשע לא טוב\"\u0004 (משלי יח, ה), כלומר, אסור לשאת פנים ולהסתכל בפני אדם רשע.","\u0003בשעת פטירתו\u0004 של רבי יהושע בן קרחה, \u0003אמר לו\u0004 רבי לרבי יהושע בן קרחה: \u0003רבי, ברכני! אמר לו: יהי רצון שתגיע לחצי ימי.\u0004 מששמע זאת רבי, שאל אותו בתמיהה: \u0003ולכולהו\u0004 \u0005[ולכולם]\u0006 לכל ימיך \u0003לא?\u0004 מדוע? \u0003אמר לו: הבאים אחריך בהמה ירעו?\u0004 כלומר, אם אתה תאריך ימים כמוני, הרי ימותו בניך בחייך ולא יוכלו לירש את משרתך ומעמדך כנשיא, ונמצא שהם לא יזכו לגדולה אלא יהיו כביכול רק רועי בהמה כל ימיהם, ומוטב איפוא שלא תאריך ימים כל כך, כדי שגם הם יזכו לגדולה.","\u0003אבוה בר איהי ומנימן בר איהי, חד\u0004 \u0005[אחד\u0006 מהם\u0005]\u0006 \u0003אמר: תיתי\u0004 \u0005[תבוא]\u0006 \u0003לי\u0004 ברכה על ש\u0003לא אסתכלי\u0004 \u0005[הסתכלתי]\u0006 \u0003בגוי, וחד\u0004 \u0005[ואחד\u0006 מהם\u0005]\u0006 \u0003אמר: תיתי\u0004 \u0005[תבוא]\u0006 \u0003לי\u0004 ברכה על ש\u0003לא עבדי\u0004 \u0005[עשיתי]\u0006 \u0003שותפות בהדי\u0004 \u0005[עם]\u0006 \u0003גוי,\u0004 כדי שלא להיות קשור באדם רשע.","מסופר עוד: \u0003שאלו תלמידיו את ר' זירא: במה הארכת ימים? אמר להם: מימי לא הקפדתי בתוך ביתי\u0004 על בני ביתי שאינם עושים רצוני, \u0003ולא צעדתי בפני מי שגדול ממני, ולא הרהרתי\u0004 בדברי תורה \u0003במבואות המטונפות\u0004 שלא לבזות התורה בכך, \u0003ולא הלכתי ארבע אמות בלא תורה ובלא\u0004 להניח \u0003תפילין, ולא ישנתי בבית המדרש לא שינת קבע ולא שינת עראי, ולא ששתי\u0004 (שמחתי) \u0003בתקלת חבירי, ולא קראתי לחבירי בחניכתו,\u0004 כלומר, בכינוי גנאי שיש לו, \u0003ואמרי לה\u0004 \u0005[ויש אומרים]:\u0006 \u0003בחכינתו\u0004 אפילו בכינוי סתם שיש לו שאינו של גנאי, לא קראתי לו.","\u0003ועוד אמר ר' יהודה: בית כנסת שחרב\u0004 — אין משתמשים במקומו לכל צורך אחר. ופירוט הדברים: \u0003אין מספידין בתוכו\u0004 את המת, \u0003ואין מפשילין\u0004 (מותחים ומתקינים) \u0003בתוכו חבלים\u0004 שצריך לשם כך מרחב, ואסור להשתמש בכך במקום שהיה בו בית כנסת, \u0003ואין פורשין לתוכו מצודות\u0004 (מלכודות) לציפרים, \u0003ואין שוטחין על גגו פירות\u0004 לייבוש, \u0003ואין עושין אותו קפנדריא\u0004 (קיצור דרך),","\u0003שנאמר: \"והשמותי את מקדשיכם\"\u0004 (ויקרא כו, לא), ומכאן אנחנו למדים: \u0003קדושתן\u0004 עליהם \u0003אף כשהן שוממין\u0004 וחרבים.","\u0003עלו בו\u0004 בבית הכנסת החרב \u0003עשבים — לא יתלוש\u0004 אותם, \u0003מפני עגמת נפש,\u0004 כדי שההזנחה תהיה נכרת, ויצטערו הבריות על כך שבית הכנסת חרב.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003בתי כנסיות אין נוהגין בהם קלות ראש,\u0004 ופירוט הדברים: \u0003אין אוכלין בהן, ואין שותין בהן,\u0004"],["\u0003ואין ניאותין\u0004 (מתקשטים) \u0003בהם, ואין מטיילין בהם, ואין נכנסין בהן בחמה מפני החמה\u0004 כדי להיות בצל, \u0003ובגשמים מפני הגשמים. ואין מספידין בהן הספד של יחיד. אבל\u0004 יש דברים שמותר לעשות בהם: \u0003קורין בהן\u0004 בתורה, \u0003ושונין בהן\u0004 במשנה, \u0003ומספידין בהן הספד של רבים,\u0004 וכגון הספד לתלמיד חכם שמת ובאים רבים להספדו ולהלווייתו","\u0003. אמר ר' יהודה: אימתי\u0004 אמרנו שהשימוש בבתי הכנסת מוגבל לדברים מסויימים — דווקא כשהם \u0003בישובן, אבל\u0004 כשעומדים \u0003בחורבנן\u0004 — \u0003מניחין אותן ועולין בהן עשבים, ולא יתלוש\u0004 עשבים אלו \u0003מפני עגמת נפש,\u0004 שיצטערו על חורבנם וישתדלו לבנותם מחדש.","ושואלים: \u0003עשבים מאן דכר שמייהו\u0004 \u0005[מי הזכיר את שמם]\u0006 שבא ר' יהודה לפרט את דינם? ומתרצים: \u0003חסורי מיחסרא והכי קתני\u0004 \u0005[חסרה\u0006 הברייתא \u0005וכך\u0006 יש \u0005לשנותה]:\u0006 \u0003ומכבדין\u0004 \u0005[מטאטאים]\u0006 \u0003אותן\u0004 את בתי הכנסת \u0003ומרביצין אותן\u0004 במים \u0003כדי שלא יעלו בהן עשבים. אמר ר' יהודה: אימתי\u0004 אמרו דבר זה — כשהם \u0003בישובן, אבל\u0004 כשעומדים הם \u0003בחורבנן\u0004 — \u0003מניחין אותן לעלות,\u0004 ואם \u0003עלו בהן עשבים\u0004 — \u0003לא יתלוש\u0004 אותם, \u0003מפני עגמת נפש.\u0004","\u0003אמר רב אסי: בתי כנסיות שבבבל, על תנאי הן עשויין.\u0004 כלומר, מראש מתנים עליהם שלא תהא בהם קדושה גמורה של בית כנסת, אלא יהא מותר להשתמש בהם לצרכי הרבים. \u0003ואף על פי כן אין נוהגין בהן\u0004 דברים שיש בהם משום \u0003קלות ראש.\u0004 ומסבירים: \u0003ומאי ניהו\u0004 \u0005[ומה הם]\u0006 דברים אלה — שאין מחשבים בהם \u0003חשבונות\u0004 של יחיד.","\u0003אמר רב אסי: בית הכנסת שמחשבין בו חשבונות — מלינים בו את המת.\u0004 ותוהים: \u0003מלינים סלקא דעתך\u0004 \u0005[עולה על דעתך]?\u0006 \u0003לא סגי\u0004 \u0005[די]\u0006 \u0003דלאו הכי\u0004 \u0005[בלא כך],\u0006 האם חובה להלין בו מת? \u0003אלא\u0004 הכוונה היא שיגרום זלזול זה שיבואו לידי פורענות, ואז \u0003לסוף שילינו בו מת מצוה\u0004 שאין לו קוברים שנמצא בעיר זו.","שנינו בברייתא: \u0003ואין נאותין בהם. אמר רבא: חכמים ותלמידיהם מותרים\u0004 בשימוש זה בבית כנסת, ש\u0003אמר ר' יהושע בן לוי: מאי\u0004 \u0005[מה\u0006 טעם\u0005]\u0006 קוראים לבית המדרש \u0003בי רבנן\u0004 \u0005[בית חכמים]\u0006 — משום שהוא \u0003ביתא דרבנן\u0004 \u0005[ביתם של חכמים],\u0006 שכיון שהם חייבים להיות בו תמיד התירו להם להיות נוהגים בו כבבית.","שנינו: \u0003ואין נכנסין בהן בחמה מפני החמה ובגשמים מפני הגשמים.\u0004 מסופר: \u0003כי הא\u0004 \u0005[כמו\u0006 מעשה \u0005זה]\u0006 ש\u0003רבינא ורב אדא בר מתנה הוו קיימי ושאלי שאילתא\u0004 \u0005[היו עומדים ושואלים שאלה]\u0006 \u0003מרבא, אתא זילחא דמיטרא\u0004 \u0005[בא שטף מטר]\u0006 עליהם, \u0003עיילי לבי כנישתא\u0004 \u0005[נכנסו לבית הכנסת]\u0006 ו\u0003אמרי\u0004 \u0005[\u0006ו\u0005אמרו]:\u0006 \u0003האי דעיילינן לבי כנישתא לאו\u0004 \u0005[זה שנכנסנו לבית הכנסת, לא]\u0006 \u0003משום מיטרא\u0004 \u0005[המטר]\u0006 הוא, שרצו שלא להירטב, \u0003אלא משום דשמעתא בעא צילותא כיומא דאסתנא\u0004 \u0005[שההלכה זקוקה לצלילות\u0006 הדעת \u0005כמו יום של רוח צפונית\u0006 שכל השמים בהירים בו\u0005],\u0006 ולכן לשם לימוד התורה נכנסו לבית הכנסת, שיוכלו לדון בענין במנוחה.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב אחא בריה\u0004 \u0005[בנו]\u0006 של \u0003רבא לרב אשי: אי אצטריך ליה לאיניש למיקרי גברא מבי כנישתא מאי\u0004 \u0005[אם צריך אדם לקרוא ל\u0006איש \u0005אחד מבית הכנסת מה\u0006 יעשה\u0005]?\u0006 שהרי אין נכנסים לשם שלא לצורך תפילה. \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003אי צורבא מרבנן\u0004 \u0005[אם תלמיד חכם]\u0006 \u0003הוא, לימא הלכתא\u0004 \u0005[שיאמר\u0006 דבר \u0005הלכה]\u0006 כשיכנס לבית הכנסת, \u0003ואם תנא\u0004 \u0005[ואם שונה\u0006 משניות\u0005]\u0006 \u0003הוא, לימא מתניתין\u0004 \u0005[שיאמר\u0006 דבר \u0005משנה]\u0006 \u0003ואי קרא\u0004 \u0005[\u0006בעל \u0005מקרא]\u0006 \u0003הוא, לימא פסוקא\u0004 \u0005[שיאמר פסוק],\u0006 \u0003ואי לא\u0004 ואם אף זאת אינו יודע, \u0003לימא ליה לינוקא\u0004 \u0005[שיאמר לו לתינוק]:\u0006 \u0003אימא לי פסוקיך\u0004 \u0005[אמור לי פסוקך]\u0006 שלמדת היום. \u0003אי נמי\u0004 \u0005[או גם כן],\u0006 \u0003נישהי פורתא וניקום\u0004 \u0005[שישהה קצת\u0006 במקום \u0005ויעמוד].\u0006","עוד שנינו בברייתא: \u0003ומספידין בהן\u0004 בבתי הכנסת \u0003הספד של רבים.\u0004 ושואלים: \u0003היכי דמי הספידא\u0004 \u0005[איך הוא\u0006 בדיוק \u0005הספד]\u0006 של \u0003רבים? מחוי\u0004 \u0005[\u0006היה \u0005מראה]\u0006 \u0003רב חסדא\u0004 בדרך נימוס: \u0003כגון הספידא דקאי ביה\u0004 \u0005[הספד שעומד,\u0006 שנמצא \u0005בו]\u0006 \u0003רב ששת,\u0004 שכיון שהוא נמצא במקום, בודאי רבים באים ונותנים כבוד לנפטר. וכיוצא בו \u0003מחוי\u0004 \u0005[\u0006היה \u0005מראה]\u0006 \u0003רב ששת: כגון הספידא דקאי ביה\u0004 \u0005[הספד שעומד,\u0006 שנמצא \u0005בו]\u0006 \u0003רב חסדא.\u0004","מסופר כעין זה: \u0003רפרם אספדה לכלתיה בבי כנישתא\u0004 \u0005[הספיד את כלתו בבית הכנסת]\u0006 ו\u0003אמר: משום יקרא דידי ודמיתא\u0004 \u0005[כבודי שלי ושל המת]\u0006 \u0003אתו כוליה עלמא\u0004 \u0005[באו הכל],\u0006 שרצה לומר שהספד זה הספד של רבים הוא. כיוצא בזה, \u0003ר' זירא ספדיה לההוא מרבנן בבי כנישתא\u0004 \u0005[הספיד חכם אחד בבית הכנסת]\u0006 ו\u0003אמר: אי משום יקרא דידי, אי משום יקרא דידיה דמיתא, אתו כולי עלמא\u0004 \u0005[אם משום כבודי שלי, אם משום כבוד שלו, של המת, באו הכל]\u0006 להספד.","אגב כך מספרים: \u0003ריש לקיש ספדיה לההוא צורבא מרבנן דשכיח בארעא\u0004 \u0005[ריש לקיש הספיד תלמיד חכם אחד שהיה מצוי בארץ]\u0006 \u0003ישראל, דהוי תני הלכתא\u0004 \u0005[שהיה שונה הלכות]\u0006 \u0003בעשרים וארבע שורתא\u0004 \u0005[שורות],\u0006 כלומר, בשורה העשרים וארבע בבית המדרש, שלא היה מגדולי החכמים, ו\u0003אמר: ווי חסרא ארעא\u0004 \u0005[אוי שחסרה ארץ]\u0006 \u0003ישראל גברא רבה\u0004 \u0005[אדם גדול].\u0006","ומסופר לעומת זאת: \u0003ההוא דהוי תני הלכתא\u0004 \u0005[אדם אחד שהיה שונה הלכות],\u0006 \u0003סיפרא וספרי ותוספתא ושכיב\u0004 \u0005[ומת],\u0006 \u0003אתו\u0004 \u0005[באו]\u0006 \u0003ואמרו ליה\u0004 \u0005[לו]\u0006 \u0003לרב נחמן: ליספדיה מר\u0004 \u0005[יספידנו אדוני]!\u0006 \u0003אמר: היכי נספדיה\u0004 \u0005[איך ניספוד אותו]?\u0006 האם נאמר \u0003הי צנא דמלי סיפרי\u0004 \u0005[אוי לסל שמלא ספרים]\u0006 ש\u0003חסר?\u0004 כלומר, גם לאחר המוות לא התייחס בכבוד גדול לאותו אדם שהיה בקי בתורה אבל הבנתו בה לא היתה עמוקה.","ומעירים: \u0003תא חזי\u0004 \u0005[בוא\u0006 ו\u0005ראה]\u0006 מה ההבדל \u0003בין תקיפי דארעא\u0004 \u0005[ארץ]\u0006 \u0003ישראל לחסידי בבל,\u0004 שריש לקיש היה מפורסם כאיש תקיף, ובהתאם לכך היתה גם התייחסותו לאדם שהיתה בו מקצת תורה.","ועוד בענין חיבוב תלמידי חכמים, \u0003תנן התם\u0004 \u0005[שנינו שם\u0006 במשנה\u0005]:\u0006 \u0003ודאשתמש בתגא\u0004 \u0005[המשתמש בכתר] —\u0006 \u0003חלף\u0004 \u0005[עובר\u0006 מן העולם\u0005].\u0006 \u0003תני\u0004 \u0005[שנה]\u0006 \u0003ריש לקיש\u0004 והסביר: \u0003זה המשתמש\u0004 (שנוהג בו כשמש שלו) \u0003במי ששונה הלכות\u0004 שהוא \u0003כתרה של תורה.\u0004","\u0003ואמר עולא: לשתמש איניש במאן דתני\u0004 \u0005[שישתמש אדם במי ששונה]\u0006 \u0003ארבעה\u0004 סדרי משנה \u0003ו\u0004ש\u0003לא לשתמש במאן דמתני\u0004 \u0005[ישתמש במי שמשנה,\u0006 מלמד אחרים\u0005]\u0006 \u0003ארבעה,\u0004 שאם צריך הוא ליזקק שישמשנו תלמיד חכם, שלא יעשה זאת בתלמיד חכם גדול. ומסופר: \u0003כי הא\u0004 \u0005[כמו\u0006 מעשה \u0005זה]\u0006 ש\u0003ריש לקיש הוה אזיל באורחא\u0004 \u0005[היה הולך בדרך]\u0006 ו\u0003מטא עורקמא דמיא\u0004 \u0005[\u0006ו\u0005הגיע לשלולית של מים],\u0006 \u0003אתא ההוא גברא ארכביה אכתפיה וקא מעבר ליה\u0004 \u0005[בא אדם אחד הרכיבו על כתפיו והיה מעביר אותו].\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 ריש לקיש תוך כדי מעבר: האם \u0003קרית\u0004 \u0005[קראת]\u0006 בתורה? \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003קרינא\u0004 \u0005[קראתי].\u0006 ושאל: האם \u0003תנית\u0004 \u0005[שנית]\u0006 משנה? ענה לו: \u0003תנינא\u0004 \u0005[שניתי]\u0006 \u0003ארבעה סדרי משנה. אמר ליה\u0004 \u0005[לו]\u0006 ריש לקיש: \u0003פסלת לך ארבעה טורי וטענת בר לקיש אכתפך\u0004 \u0005[\u0006אתה \u0005חצבת לך ארבעה הרים\u0006 אלה \u0005ואתה טוען את בן לקיש על כתפך]?!\u0006 \u0003שדי בר לקישא במיא\u0004 \u0005[זרוק\u0006 את \u0005בן לקיש במים]!\u0006 כלומר, אין זה מן הראוי שארכב על גבי אדם כמוך.","\u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003ניחא לי דאשמעינן למר\u0004 \u0005[נוח לי לשמש את אדוני]\u0006 ושמח אני בזכות זו. אמר לו ריש לקיש: \u0003אי הכי גמור מיני הא מלתא\u0004 \u0005[אם כך, למד ממני דבר זה]\u0006 ש\u0003אמר ר' זירא,\u0004 ועל ידי כך תוכל להיחשב כתלמידי ותהיה כמשמש את רבך: \u0003בנות ישראל הן החמירו על עצמן שאפילו רואות טיפת דם כחרדל יושבות עליו שבעה נקיים,\u0004 שאף שמדין תורה רק אם רואה אשה דם במשך שלושה ימים רצופים שלא בזמן ווסתה נעשית היא זבה, וצריכה לבדוק עצמה עד למנין שבעה ימים נקיים, מכל מקום בנות ישראל החמירו על עצמן לנהוג דין זבה אפילו בטיפת דם אחת.","\u0003תנא דבי אליהו: כל השונה הלכות מובטח לו שהוא בן עולם הבא, שנאמר: \"הליכות עולם לו\"\u0004 (חבקוק ג, ו) \u0003אל תקרי\u0004 \u0005[תקרא]\u0006 \u0003\"הליכות\" אלא \"הלכות\",\u0004 כלומר, כל השונה הלכות — עולם לו.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006"],["\u0003מבטלין תלמוד תורה להוצאת המת,\u0004 כלומר, לטפל בו וללוותו \u0003ולהכנסת הכלה. אמרו עליו על ר' יהודה בר' אילעאי שהיה מבטל תלמוד תורה להוצאת המת ולהכנסת הכלה.\u0004 ומעירים: \u0003במה דברים אמורים\u0004 שמבטלים תלמוד תורה — \u0003בשאין שם כל צורכו\u0004 של המת להלווייתו וצריך להוסיף ולכבדו במלווים, \u0003אבל\u0004 אם \u0003יש שם כל צורכו — אין מבטלין.\u0004","ושואלים: \u0003וכמה כל צורכו? אמר רב שמואל בר איניא משמיה\u0004 \u0005[משמו]\u0006 של \u0003רב: תריסר אלפי גברי ושיתא אלפי שיפורי\u0004 \u0005[שנים עשר אלף איש וששת אלפים\u0006 תוקעי \u0005שופרות],\u0006 שהיו נוהגים לתקוע בהם כאות אבל. \u0003ואמרי לה\u0004 \u0005[ויש אומרים]\u0006 נוסחה אחרת: \u0003תריסר אלפי גברי ומינייהו שיתא אלפי שיפורי\u0004 \u0005[שנים עשר אלף אנשים ומהם ששת אלפים שופרות].\u0006 \u0003עולא אמר:\u0004 שיעור די צורכו הוא \u0003כגון דחייצי גברי מאבולא\u0004 \u0005[שחוצצים אנשים משער\u0006 העיר\u0005]\u0006 \u0003עד\u0004 המקום בבית הקברות הנקרא \u0003סיכרא.\u0004","\u0003רב ששת אמר: כנתינתה\u0004 של התורה \u0003כך נטילתה,\u0004 כלומר, בנטילתה מן העולם, כאשר מת תלמיד חכם, צריך לנהוג בה באותה מידת כבוד כבשעת נתינתה, דהיינו: \u0003מה נתינתה\u0004 של תורה \u0003בששים רבוא,\u0004 שהרי ניתנה במעמד הר סיני לשישים רבוא אנשים, \u0003אף נטילתה\u0004 צריכה להיות \u0003בששים רבוא.\u0004 ומעירים: \u0003הני מילי למאן דקרי ותני\u0004 \u0005[דברים אלה,\u0006 שיעורים אלה, אמרו \u0005למי שקורא ושונה\u0006 לעצמו\u0005],\u0006 \u0003אבל למאן דמתני\u0004 \u0005[למי שמלמד\u0006 אחרים\u0005]\u0006 גדול כבודו יותר ו\u0003לית ליה שיעורא\u0004 \u0005[אין לו שיעור\u0006 כלל\u0005]\u0006 לכבודו.","\u0003תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005]\u0006 \u0003ר' שמעון בן יוחי אומר: בוא וראה כמה חביבין ישראל לפני הקדוש ברוך הוא, שבכל מקום שגלו\u0004 ישראל — \u0003שכינה עמהן. גלו למצרים — שכינה עמהן, שנאמר: \"הנגלה נגליתי לבית אביך בהיותם במצרים\"\u0004 (שמואל א' ב, כז), הרי ששכינה היתה עמם ונגלתה להם שם. \u0003גלו לבבל — שכינה עמהן, שנאמר: \"למענכם שלחתי בבלה\"\u0004 (ישעיהו מג, יד). \u0003ואף כשהן עתידים להגאל\u0004 — \u0003שכינה עמהם, שנאמר: \"ושב ה' אלהיך את שבותך\"\u0004 (דברים ל, ג), ומדייקים: \u0003\"והשיב\" לא נאמר,\u0004 כלומר, לא שיגרום שישובו, \u0003אלא\u0004 נאמר \u0003\"ושב\",\u0004 והלשון הזאת \u0003מלמד שהקדוש ברוך הוא שב עמהם מבין הגליות,\u0004 משמע שאף אז תהיה השכינה מצויה עמהם.","ושואלים: אם שכינה עמהם, \u0003בבבל היכא\u0004 \u0005[היכן]\u0006 שרויה שכינה? \u0003אמר אביי: בבי כנישתא\u0004 \u0005[בבית הכנסת]\u0006 של \u0003הוצל\u0004 שהיה עתיק וחשוב מאוד, \u0003ובבי כנישתא \"דשף ויתיב\"\u0004 \u0005[ובבית הכנסת שנפל וישב]\u0006 \u0003בנהרדעא,\u0004 משום שכך היה שמו של בית הכנסת. \u0003ולא תימא הכא והכא\u0004 \u0005[ולא תאמר כאן וכאן]\u0006 שכינה שורה באותו זמן, \u0003אלא זמנין הכא וזמנין הכא\u0004 \u0005[פעמים כאן ופעמים כאן],\u0006 לפעמים בהוצל ולפעמים בנהרדעא. \u0003אמר אביי: תיתי לי\u0004 \u0005[תבוא לי\u0006 ברכה\u0005],\u0006 \u0003דכי מרחיקנא\u0004 \u0005[שכאשר אני רחוק]\u0006 אפילו \u0003פרסה, עיילנא ומצלינא התם\u0004 \u0005[אני נכנס ומתפלל שם],\u0006 בבתי כנסת אלה, מפני כבודם וקדושתם. מסופר: \u0003אבוה\u0004 \u0005[אביו]\u0006 של \u0003שמואל ולוי הוו יתבי בכנישתא דשף ויתיב\u0004 \u0005[היו יושבים בבית הכנסת שנפל וישב]\u0006 \u0003בנהרדעא, אתיא\u0004 \u0005[באה]\u0006 \u0003שכינה, שמעו קול ריגשא\u0004 \u0005[רעש],\u0006 \u0003קמו ונפקו\u0004 \u0005[ויצאו].\u0006","אמנם, מסופר, כי \u0003רב ששת הוה יתיב בבי כנישתא דשף ויתיב\u0004 \u0005[היה יושב בבית הכנסת שנפל וישב]\u0006 \u0003בנהרדעא, אתיא\u0004 \u0005[באה]\u0006 \u0003שכינה ולא נפק\u0004 \u0005[יצא].\u0006 \u0003אתו\u0004 \u0005[באו]\u0006 \u0003מלאכי השרת וקא מבעתו ליה\u0004 \u0005[והיו מפחידים אותו].\u0006 \u0003אמר לפניו: רבונו של עולם, עלוב ושאינו עלוב מי נדחה מפני מי\u0004 — ודאי ראוי הוא שידחה זה שאינו עלוב, והלוא אני עיוור ועלוב, ומדוע דוחה אתה אותי מפני המלאכים? \u0003אמר להו\u0004 \u0005[להם]\u0006 הקדוש ברוך הוא למלאכים: \u0003שבקוהו\u0004 \u0005[הניחו לו].\u0006","נאמר: \u0003\"ואהי להם למקדש מעט\u0004 בארצות אשר באו שם\u0003\"\u0004 (יחזקאל יא, טז), \u0003אמר ר' יצחק: אלו בתי כנסיות ובתי מדרשות שבבבל. ור' אלעזר אמר: זה בית רבנו\u0004 (רב) \u0003שבבבל,\u0004 שממנו יצאה תורה לכל העולם.","\u0003דרש רבא: מאי דכתיב\u0004 \u0005[מהו שנאמר]:\u0006 \u0003\"ה' מעון אתה היית לנו\"\u0004 (תהלים צ, א), כוונתו: \u0003אלו בתי כנסיות ובתי מדרשות. אמר אביי: מריש הואי גריסנא בביתא ומצלינא בבי כנשתא\u0004 \u0005[בתחילה הייתי לומד בבית ומתפלל בבית הכנסת],\u0006 \u0003כיון דשמעית להא דקאמר\u0004 \u0005[כיון ששמעתי\u0006 והבנתי \u0005זאת שאמר]\u0006 \u0003דוד\u0004 המלך: \u0003\"ה' אהבתי מעון ביתך\"\u0004 (תהלים כו, ח), \u0003הואי גריסנא בבי כנישתא\u0004 \u0005[הייתי לומד בבית הכנסת],\u0006 שהרי זה מראה על אהבה למקום שיש בו השראת שכינה.","\u0003תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005],\u0006 \u0003ר' אלעזר הקפר אומר: עתידין בתי כנסיות ובתי מדרשות שבבבל שיקבעו בארץ ישראל, שנאמר: \"כי כתבור בהרים וככרמל בים יבוא\"\u0004 (ירמיהו מו, יח), ומדרש אגדה הוא שהתבור בא מן ההרים והכרמל בא מן הים כדי שתינתן עליהם התורה, \u0003והלא דברים קל וחומר: מה תבור וכרמל שלא באו אלא לפי שעה ללמוד תורה,\u0004 הרי בשכר בואם הם \u0003נקבעים\u0004 להיות \u0003בארץ ישראל, בתי כנסיות ובתי מדרשות שקורין ומרביצים בהם תורה — על אחת כמה וכמה\u0004 שיזכו וייקבעו כולם בארץ ישראל.","\u0003דרש בר קפרא: מאי דכתיב\u0004 \u0005[מהו שנאמר]:\u0006 \u0003\"למה תרצדון הרים גבננים\u0004 ההר חמד אלהים לשבתו\u0003\"\u0004 (תהלים סח, יז), \u0003יצתה בת קול ואמרה להם,\u0004 לכל ההרים שבאו שתינתן עליהם התורה: \u0003למה תרצו דין\u0004 (\"תרצדון\") \u0003עם סיני?\u0004 הלוא \u0003כולכם בעלי מומים אתם אצל\u0004 (כלפי) הר \u0003סיני,\u0004 וראיה לדבר ש\"גבנונים\" הם בעלי מומים: \u0003כתיב הכא\u0004 \u0005[נאמר כאן]\u0006 \u0003\"גבנונים\" וכתיב התם\u0004 \u0005[ונאמר שם]\u0006 בענין המומים: \u0003\"או גבן או דק\"\u0004 (ויקרא כא, כ). \u0003אמר רב אשי: שמע מינה\u0004 \u0005[למד מכאן]\u0006 \u0003האי מאן דיהיר\u0004 \u0005[מי שהוא גאוותן]\u0006 — \u0003בעל מום הוא,\u0004 שהרי מומם של ההרים האלה היה גדלותם, ובשל כך יהירותם, לעומת הר סיני שהיה נמוך.","שנינו במשנה: \u0003אין עושים אותו\u0004 את בית הכנסת \u0003קפנדריא\u0004 (קיצור דרך). ושואלים \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"קפנדריא\"? אמר רבא: קפנדריא כשמה.\u0004 ושואלים: מהו אם כן \u0003כשמה?\u0004 ומסבירים שאנו דורשים את שמה בנוטריקון, \u0003כמאן דאמר\u0004 \u0005[כמי שאומר]:\u0006 \u0003אדמקיפנא אדרי, איעול בהא\u0004 \u0005[עד שאני מקיף את שורות\u0006 הבתים ואאריך דרכי, \u0005אכנס בזו],\u0006 וזוהי \"קפנדריא\".","\u0003אמר ר' אבהו: אם היה\u0004 המקום שעליו בנו את בית הכנסת \u0003שביל מעיקרא\u0004 \u0005[מתחילה]\u0006 לפני בנייתו — \u0003מותר,\u0004 שאין כבוד בית הכנסת מבטל את זכות הרבים לעבור בשביל זה.","\u0003אמר רב נחמן בר יצחק: הנכנס\u0004 לבית הכנסת מלכתחילה \u0003על מנת שלא לעשות קפנדריא\u0004 והתחרט, כשיוצא — \u0003מותר לעשותו קפנדריא,\u0004 שהרי לא לשם זה נכנס. \u0003ואמר ר' חלבו אמר רב הונא: הנכנס לבית הכנסת להתפלל מותר\u0004 וראוי לו \u0003לעשותו\u0004 מלכתחילה \u0003קפנדריא, שנאמר: \"ובבוא עם הארץ לפני ה' במועדים הבא דרך שער צפון להשתחות יצא דרך שער נגב\"\u0004 (יחזקאל מו, ט), משמע שדרך כבוד היא שאין חוזרים מאותו פתח, אלא עוברים בו לצד האחר.","שנינו במשנה: \u0003עלו בו\u0004 בבית הכנסת \u0003עשבים\u0004 — \u0003לא יתלוש מפני עגמת נפש.\u0004 ומקשים, \u0003והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]:\u0006 \u0003אינו תולש ומאכיל\u0004 לבהמתו, \u0003אבל תולש ומניח\u0004 במקום, הרי שתלישת העשבים בכלל מותרת! ומשיבים: \u0003כי תנן נמי מתניתין\u0004 \u0005[כאשר שנינו גם כן במשנתנו]\u0006 שאסור לתלוש — \u0003תולש ומאכיל תנן\u0004 \u0005[שנינו]\u0006 ולא לענין תלישה סתם.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003בית הקברות, אין נוהגין בהן קלות ראש.\u0004 ולמשל: \u0003אין מרעין בהם בהמה\u0004 בעשבים שצמחו שם, \u0003ואין מוליכין בהן\u0004 (מעבירים דרכם) \u0003אמת המים, ואין מלקטין בהם עשבים\u0004 להאכיל לבהמתו, \u0003ואם ליקט — שורפן במקומן, מפני כבוד מתים.\u0004","ושואלים: הביטוי \"מפני כבוד מתים\", \u0003אהייא\u0004 \u0005[על\u0006 הדין של \u0005מה]\u0006 אמר? \u0003אילימא אסיפא\u0004 \u0005[אם תאמר על סופה]\u0006 של הברייתא — \u0003כיון ששורפן במקומן מאי\u0004 \u0005[מה]\u0006 \u0003כבוד מתים איכא\u0004 \u0005[יש כאן]?\u0006 \u0003אלא\u0004 ביטוי זה נאמר \u0003ארישא\u0004 \u0005[\u0006על \u0005ראשה,\u0006 תחילתה של המשנה\u0005]\u0006 והוא הסבר מדוע אין נוהגים קלות ראש בבית הקברות — מפני כבוד מתים.","\u0003ראש חדש אדר שחל להיות בשבת — קורין\u0004 (קוראים) באותה שבת \u0003בפרשת שקלים. חל\u0004 ראש חודש \u0003להיות בתוך השבת\u0004 (באמצע השבוע) — \u0003מקדימין לשעבר,\u0004 קוראים פרשת שקלים בשבת הקודמת, \u0003ומפסיקים\u0004 שלא לקרוא פרשה מיוחדת אלא כסדר הקריאה הרגיל \u0003לשבת\u0004 ה\u0003אחרת\u0004 השבת הראשונה של חודש אדר.","\u0003ב\u0004שבת ה\u0003שניה\u0004 של אדר סמוך לפורים קוראים פרשת \u0003\"זכור\"\u0004 (דברים כה, יז-יט). \u0003ב\u0004שבת ה\u0003שלישית\u0004 באדר קוראים פרשת \u0003פרה אדומה\u0004 (במדבר פרק יט). \u0003ב\u0004שבת ה\u0003רביעית\u0004 קוראים \u0003\"החדש הזה לכם\"\u0004 (שמות יב, ב). \u0003ב\u0004שבת ה\u0003חמישית חוזרין לכסדרן\u0004 וקוראים לפי סדר הפרשיות הקבוע.","וקובעים כלל: \u0003לכל\u0004 הימים המיוחדים \u0003מפסיקין\u0004 ואין קוראים כסדר פרשת שבוע אלא בענין היום, הן \u0003בראשי חדשים, בחנוכה, ובפורים, בתעניות, ובמעמדות, וביום הכפורים,\u0004 שאם חל אחד מימים אלה בשבת, אין קוראים את סדר הקריאה הרגיל בשלימותו אלא קריאה המיוחדת לאותו היום.","\u0003תנן התם\u0004 \u0005[שנינו שם\u0006 במשנה\u0005]:\u0006 \u0003באחד באדר משמיעין על השקלים,\u0004 כלומר, מודיעים לציבור שצריכים לתת שקלים למקדש"],["\u0003ועל הכלאים.\u0004","ושואלים: \u0003בשלמא\u0004 \u0005[נניח]\u0006 שמשמיעים \u0003על\u0004 כך שיש לעקור את צמחי \u0003הכלאים\u0004 שצמחו בתוך התבואה — משום ש\u0003זמן זריעה היא\u0004 ובחודש זה מתחילים הצמחים להיות ניכרים והרי זה הזמן הראוי לטפל בענין זה, \u0003אלא\u0004 שיש סיבה להשמיע \u0003על השקלים\u0004 בזמן הזה \u0003מנלן\u0004 \u0005[מנין לנו]?\u0006","\u0003אמר ר' טבי אמר ר' יאשיה:\u0004 ש\u0003אמר קרא\u0004 \u0005[הכתוב]:\u0006 \u0003\"זאת עלת חדש בחדשו\u0004 לחדשי השנה\u0003\"\u0004 (במדבר כח, יד), שלשון \"חודש\" הנזכרת בפסוק זה כמה פעמים משמעה גם חידוש — \u0003אמרה תורה:\u0004 יש לך חודש אחד שעליו אתה מצווה \u0003חדש והבא קרבן מתרומה חדשה,\u0004 ובמסכת ראש השנה (דף ז,א) נלמד הדבר בגזירה שווה שהכוונה לחודש ניסן","\u0003וכיון\u0004 שבחודש \u0003ניסן בעי אקרובי\u0004 \u0005[צריך להקריב]\u0006 תמידים ומוספים \u0003מתרומה חדשה\u0004 משקלים שנדבו לשנה חדשה זו, \u0003קדמינן וקרינן\u0004 \u0005[מקדימים אנו וקוראים אנו]\u0006 פרשת שקלים \u0003באחד באדר, כי היכי דליתו\u0004 \u0005[כדי שיגיעו]\u0006 \u0003שקלים למקדש\u0004 בתוך חודש זה, ומעירים: אם כן,","\u0003כמאן\u0004 \u0005[כמי]\u0006 משנה זו — ש\u0003לא כ\u0004שיטת \u0003רבן שמעון בן גמליאל. דאי\u0004 \u0005[שאם]\u0006 תאמר שהיא כשיטת \u0003רבן שמעון בן גמליאל, האמר\u0004 \u0005[הרי אמר]\u0006 שדי להקדים רק \u0003שתי שבתות, דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003שואלין\u0004 ודורשים \u0003בהלכות הפסח קודם לפסח שלשים יום. רבן שמעון בן גמליאל אומר: שתי שבתות.\u0004 משמע שלדעתו די בשבועיים כדי להודיע על מאורע!","ודוחים: \u0003אפילו תימא\u0004 \u0005[תאמר]\u0006 שהוא כדעת \u0003רבן שמעון בן גמליאל,\u0004 אלא שלגבי השקלים יש להקדים ולהודיע כבר מראש חודש אדר, \u0003כיון\u0004 ש\u0003אמר מר\u0004 \u0005[החכם]:\u0006 \u0003בחמשה עשר בו\u0004 באדר \u0003שולחנות\u0004 שבהם אוספים ומחליפים את השקלים למקדש \u0003יושבין\u0004 עדיין \u0003במדינה\u0004 (בכל הארץ) \u0003ובעשרים וחמישה\u0004 באדר \u0003יושבין במקדש,\u0004 ו\u0003משום שולחנות\u0004 שנעשים בחמישה עשר, \u0003קדמינן וקרינן\u0004 \u0005[מקדימים וקוראים]\u0006 מתחילת החודש, להודיע לאנשים שבועיים לפני זמן זה לתת את הכסף לשולחנים.","נאמר במשנה שקוראים פרשת שקלים. ושואלים: \u0003מאי\u0004 \u0005[מהי]\u0006 \u0003פרשת שקלים\u0004 זו שאמרנו? \u0003רב אמר:\u0004 היא הפרשה של \u0003\"צו את בני ישראל ואמרת אליהם את קרבני לחמי\"\u0004 (במדבר כח, א והלאה), המדברת בענין קרבנות התמידים והמוספים. \u0003ושמואל אמר:\u0004 פרשת שקלים היא פרשת \u0003\"כי תשא\"\u0004 (שמות ל, יא-טז).","ושואלים: \u0003בשלמא למאן דאמר\u0004 \u0005[נניח ל\u0006שיטת \u0005מי שאומר]\u0006 שהיא פרשת \u0003\"כי תשא\", היינו דקרי\u0004 \u0005[זהו\u0006 הטעם \u0005ש\u0006הוא \u0005קורא]\u0006 \u0003לה פרשת שקלים, דכתיב\u0004 \u0005[ש\u0006הרי \u0005נאמר]\u0006 \u0003בה\u0004 במפורש \u0003\"שקלים\". אלא למאן דאמר\u0004 \u0005[ל\u0006שיטת \u0005מי שאומר]\u0006 כי זאת פרשת \u0003\"את קרבני לחמי\", (הכא) מידי\u0004 \u0005[וכי (כאן)]\u0006 \u0003\"שקלים\" כתיבי התם\u0004 \u0005[נאמרו שם]?\u0006 ומשיבים: \u0003אין\u0004 \u0005[כן],\u0006 \u0003טעמא מאי\u0004 \u0005[מהו הטעם]\u0006 שמביאים שקלים בכל שנה — \u0003כ\u0004שיטת \u0003ר' טבי\u0004 שיש להביא כספים חדשים לקרבנות הציבור בשנה המתחילה בניסן, ולכן קוראים בפרשה זו המדברת בענין הקרבנות.","ושואלים לצד אחר: \u0003בשלמא למאן דאמר\u0004 \u0005[נניח ל\u0006שיטת \u0005מי שאומר]\u0006 כי פרשת שקלים היא פרשת \u0003\"צו את בני ישראל\", משום דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"קרבנות\" התם\u0004 \u0005[שם],\u0006 \u0003כ\u0004שיטת \u0003ר' טבי,\u0004 ששוקלים שקלים באדר לצורך הקרבנות האמורים בפרשה זו. \u0003אלא למאן דאמר\u0004 \u0005[ל\u0006שיטת \u0005מי שאומר]\u0006 שקוראים פרשת \u0003\"כי תשא\", \"קרבנות\" מי כתיבי\u0004 \u0005[האם כתובים\u0006 שם\u0005]?\u0006 הלא שם רק ענין תרומת \u0003שקלים לאדנים\u0004 של המשכן \u0003כתיבי\u0004 \u0005[כתובים]!\u0006","ומשיבים: \u0003כדתני\u0004 \u0005[כפי ששנה]\u0006 על זה \u0003רב יוסף\u0004 ואמר: \u0003שלש תרומות הן\u0004 שנרמזו בפרשת השקלים ב\"כי תשא\". שקלים שנימנו מתחילה \u0003של מזבח — למזבח, ושל אדנים — לאדנים, ושל בדק הבית — לבדק הבית.\u0004 הרי שבכלל תרומת השקלים היתה גם תרומה לקרבנות שעל המזבח.","ועוד שואלים: \u0003בשלמא למאן דאמר\u0004 \u0005[נניח ל\u0006שיטת \u0005מי שאומר]\u0006 שפרשת שקלים היא \u0003\"כי תשא\" — היינו דשני\u0004 \u0005[זהו ששונה]\u0006 \u0003האי\u0004 \u0005[זה]\u0006 \u0003ראש חדש\u0004 אדר שחל להיות בשבת \u0003משאר ראשי חדשים\u0004 החלים בשבת שקוראים בהם את פרשת הקרבנות,","\u0003אלא למאן דאמר\u0004 \u0005[ל\u0006שיטת \u0005מי שאומר]\u0006 \u0003\"צו\u0004 את בני ישראל ואמרת אליהם \u0003את קרבני\u0004 לחמי לאשי \u0003\", מאי שני\u0004 \u0005[במה שונה]\u0006 הפרשה הנקראת בשבת זו מזו הנקראת בכל שבת ראש חודש? ומשיבים: \u0003שני\u0004 \u0005[שונה]\u0006 באופן זה: ש\u0003אילו\u0004 שאר \u0003ראשי חדשים\u0004 החלים בשבת \u0003קרו שיתא בענינא דיומא\u0004 \u0005[קוראים שישה בעניינו של יום]\u0006 \u0003וחד\u0004 \u0005[ואחד]\u0006 \u0003ב\u0004ענין \u0003ראש חודש, ואילו האידנא\u0004 \u0005[עכשיו],\u0006 בראש חודש אדר שחל בשבת, \u0003כולהו\u0004 \u0005[כולם]\u0006 קוראים \u0003ב\u0004של \u0003ראש חודש.\u0004","ושואלים: \u0003הניחא למאן דאמר\u0004 \u0005[\u0006תירוץ \u0005זה\u0006 שאמרנו \u0005נוח ל\u0006דעת \u0005מי שאומר]\u0006 \u0003לסדר פרשיות הוא חוזר,\u0004 שבארבע שבתות מיוחדות אלה קוראים רק פרשה המיוחדת להן ולא דבר אחר וכמסיים את קריאת ארבעה פרשיות אלו חוזר לפרשת השבוע כסדר הרגיל.","\u0003אלא למאן דאמר\u0004 \u0005[ל\u0006שיטת \u0005מי שאמר]\u0006 כי ל\u0003סדר ההפטרות הוא חוזר\u0004 שאין קריאת התורה כולה בפרשיות האמורות, אלא רק המפטיר, \u0003ופרשתא דיומא קרינן\u0004 \u0005[ו\u0006את \u0005פרשת היום קוראים אנו]\u0006 לפי הסדר, אם כן \u0003מאי שני\u0004 \u0005[במה שונה]\u0006 ראש חודש זה מן האחרים?","ומשיבים: \u0003שני\u0004 \u0005[שונה],\u0006 ש\u0003אילו\u0004 שאר \u0003ראשי חדשים קרי שיתא בעניינא דיומא\u0004 \u0005[קוראים שישה בענין היום]\u0006 בסדר הפרשיות הרגיל \u0003וחד קרי\u0004 \u0005[ואחד קורא]\u0006 בשל \u0003ראש חודש ואילו האידנא קרי תלתא בעניינא דיומא\u0004 \u0005[עכשיו\u0006 בפרשת שקלים \u0005קוראים שלושה בענין היום]\u0006 \u0003וארבעה קרו\u0004 \u0005[קוראים]\u0006 בשל \u0003ראש חודש.\u0004","\u0003מיתיבי\u0004 \u0005[מקשים]\u0006 ממה ששנינו בתוספתא: \u0003ראש חודש אדר שחל להיות בשבת קורין בפרשת שקלים, ומפטירין ב\u0004ענין של \u0003יהוידע הכהן\u0004 (מלכים ב' יב, א-ז). \u0003בשלמא למאן דאמר\u0004 \u0005[נניח ל\u0006שיטת \u0005מי שאומר]\u0006 שקוראים \u0003\"כי תשא\", היינו\u0004 \u0005[זו\u0006 הסיבה\u0005]\u0006 ש\u0003מפטירים ביהוידע הכהן דדמי ליה\u0004 \u0005[ש\u0006כן הוא \u0005דומה לו]\u0006 בעניינו, \u0003דכתיב\u0004 \u0005[שנאמר]\u0006 בפרשת יהוידע: \u0003\"כסף נפשות ערכו\"\u0004 (מלכים ב' יב, ה),","\u0003אלא למאן דאמר\u0004 \u0005[ל\u0006שיטת \u0005מי שאומר]\u0006 כי קוראים את פרשת \u0003\"את קרבני לחמי\", מי דמי\u0004 \u0005[האם דומה]\u0006 הדבר? ומשיבים: הדבר \u0003דמי\u0004 \u0005[דומה]\u0006 כאשר מבינים את טעם מתן השקלים כפי שאמר \u0003ר' טבי.\u0004","\u0003מיתיבי\u0004 \u0005[מקשים],\u0006 ממה ששנינו: \u0003חל\u0004 ראש חודש אדר \u0003להיות בפרשה הסמוכה לה\u0004 (לפרשת השקלים), בין שסמוכה \u0003מלפניה, בין לאחריה — קורין אותה\u0004 בזמנה \u0003וכופלין אותה\u0004 בשבת הבאה, שקוראים את אותה פרשה פעם נוספת.","ומעתה, \u0003בשלמא למאן דאמר\u0004 \u0005[נניח ל\u0006שיטת \u0005מי שאומר]\u0006 שקוראים פרשת \u0003\"כי תשא\" — היינו דמתרמי בההוא זימנא\u0004 \u0005[זהו שמזדמן באותו זמן],\u0006 שפעמים פרשת השבוע הסמוכה היא פרשת \"כי תשא\",","\u0003אלא למאן דאמר\u0004 \u0005[ל\u0006שיטת \u0005מי שאומר]\u0006 שקוראים \u0003\"צו... את קרבני\", מי מתרמי בההוא זימנא\u0004 \u0005[האם מזדמן באותו זמן]\u0006 שיקראו פרשה זו? והרי פרשה זו נקראת בקיץ! ומשיבים: \u0003אין\u0004 \u0005[כן]\u0006 אפשרי שיקרה כן \u0003לבני מערבא\u0004 \u0005[ארץ ישראל]\u0006 \u0003דמסקי לדאורייתא בתלת שנין\u0004 \u0005[ש\u0006הם \u0005גומרים את\u0006 קריאת \u0005התורה בשלוש שנים]\u0006 ולא בשנה אחת, ויתכן איפוא שיקראו בפרשת \"צו את קרבני\" בחודש אדר.","\u0003תניא כוותיה\u0004 \u0005[שנויה\u0006 ברייתא \u0005כשיטתו]\u0006 של \u0003שמואל: ראש חודש אדר שחל להיות בשבת — קורין \"כי תשא\" ומפטירין ב\"יהוידע הכהן\".\u0004","\u0003אמר ר' יצחק נפחא\u0004 \u0005[הנפח]:\u0006 \u0003ראש חודש אדר שחל להיות בשבת\u0004 עצמה — \u0003מוציאין\u0004 באותה שבת \u0003שלש\u0004 ספרי \u0003תורות, וקורין בהן, אחד בעניינו של יום\u0004 לפי סדר הפרשיות הרגיל (פרשת השבוע) \u0003ואחד בשל ראש חודש, ואחד ב\"כי תשא\"\u0004 שהיא פרשת שקלים. \u0003ואמר ר' יצחק נפחא: ראש חודש טבת שחל להיות בשבת\u0004 והוא תמיד בתוך חנוכה, \u0003מביאין שלש תורות וקורין בהן, אחד בעניינו של יום\u0004 לפי סדר הפרשיות \u0003ואחד ב\u0004של \u0003ראש חודש, ואחד\u0004 בפרשה הנקראת \u0003בחנוכה.\u0004","ומעירים: \u0003וצריכא\u0004 \u0005[וצריך]\u0006 שיאמר את שתי ההלכות, ואינן נלמדות זו מזו. \u0003דאי איתמר בהא\u0004 \u0005[שאילו\u0006 היה \u0005נאמר\u0006 רק \u0005בזו]\u0006 של ראש חודש טבת, הייתי אומר: \u0003בהא קאמר\u0004 \u0005[בזאת אמר]\u0006 \u0003ר' יצחק, אבל בהך\u0004 \u0005[בזו]\u0006 של אדר \u0003כרב סבירא ליה\u0004 \u0005[סבור הוא],\u0006 ש\u0003אמר\u0004 ש\u0003פרשת שקלים\u0004 היא \u0003\"את קרבני לחמי\", ו\u0004ממילא \u0003בשתי\u0004 ספרי \u0003תורות סגי\u0004 \u0005[מספיק],\u0006 על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 שגם באדר קוראים בשלושה ספרי תורה.","ושואלים: \u0003ולימא הא ולא בעיא הך\u0004 \u0005[ושיאמר זאת\u0006 לגבי פרשת שקלים \u0005ולא צריכה האחרת]!\u0006 ומשיבים: אכן, אינה צריכה, אלא \u0003חדא\u0004 \u0005[אחת]\u0006 \u0003מכלל חבירתה איתמר\u0004 \u0005[נאמרה],\u0006 שהוא אמר הלכה מפורשת בפרשת שקלים, ומכאן למדו לענין ראש חודש בחנוכה.","\u0003איתמר\u0004 \u0005[נאמר]\u0006 שחלקו אמוראים בבעיה הבאה: \u0003ראש חדש טבת שחל להיות ב\u0004יום \u0003חול,\u0004 כיצד קוראים? \u0003אמר ר' יצחק\u0004 נפחא: \u0003קרו תלתא\u0004 \u0005[קוראים שלושה]\u0006 \u0003ב\u0004פרשת \u0003ראש חדש, וחד\u0004 \u0005[ואחד]\u0006 קורא \u0003ב\u0004ענין \u0003חנוכה. ורב דימי דמן חיפה אמר: קרו תלתא\u0004 \u0005[קוראים שלושה]\u0006 \u0003בחנוכה וחד\u0004 \u0005[ואחד]\u0006 \u0003בראש חדש.\u0004","\u0003אמר ר' מני: כוותיה\u0004 \u0005[כשיטתו]\u0006 של \u0003ר' יצחק נפחא מסתברא\u0004 \u0005[מסתבר]\u0006 לומר לפי הכלל: \u0003תדיר ושאינו תדיר — תדיר קודם.\u0004 וכיון שראש חודש תדיר יותר מחנוכה, עיקר הקריאה צריכה להיות בעניינו.","\u0003אמר ר' אבין: כוותיה\u0004 \u0005[כשיטתו]\u0006 של \u0003רב דימי מסתברא\u0004 \u0005[מסתבר]\u0006 לומר, ומדוע — \u0003מי גרם לרביעי שיבא,\u0004 מי גרם שיקראו ארבעה אנשים בספר התורה — \u0003ראש חדש\u0004 שהרי בחנוכה קוראים רק שלושה, \u0003הלכך\u0004 \u0005[על כן]\u0006 \u0003רביעי בראש חדש בעי מיקרי\u0004 \u0005[צריך לקרוא],\u0006 להדגיש שתוספת הרביעי מפני ראש חודש היא.","ושואלים: \u0003מאי הוי עלה\u0004 \u0005[מה היה עליה],\u0006 מה פוסקים בשאלה זו? \u0003רב יוסף אמר: אין משגיחין בראש חודש\u0004 לעשות אותו עיקר הקריאה אלא קוראים בענין חנוכה שלושה, \u0003ורבה אמר: אין משגיחין בחנוכה\u0004 לעשות אותו עיקר הקריאה, אלא קוראים בענין ראש חודש שלושה\u0003. והלכתא\u0004 \u0005[וההלכה]:\u0006 \u0003אין משגיחין בחנוכה, וראש חודש\u0004 הוא שצריך להיות \u0003עיקר\u0004 הקריאה.","\u0003איתמר\u0004 \u0005[נאמר]:\u0006 \u0003חל להיות\u0004 ראש חודש אדר בשבת, ופרשת שבוע היא \u0003\"ואתה תצוה\",\u0004 מה עושים? \u0003אמר ר' יצחק נפחא: קרו שיתא\u0004 \u0005[קוראים שישה]\u0006 \u0003מ\"ואתה תצוה\"\u0004 (שמות כז, כ), \u0003עד \"כי תשא\"\u0004 (הפרשה הבאה אחריה) \u0003וחד\u0004 \u0005[ואחד]\u0006 קורא \u0003מ\u0004תחילת הפרשה של \u0003\"כי תשא\"\u0004 (שמות ל, יא) \u0003עד\u0004 הפרשה המתחילה \u0003\"ועשית\u0004 כיור נחושת\u0003\"\u0004 (שמות ל, יז). \u0003אמר אביי:\u0004"],["\u0003אמרי\u0004 \u0005[אומרים]\u0006 הבריות: \u0003אוקומי הוא דקא מוקמי התם\u0004 \u0005[עומדים\u0006 ומפסיקים \u0005הם שם]\u0006 שהרי הוא המשך הפרשה, ואין יודעים שקוראים לשם פרשת שקלים וסבורים שכאן סיום הפרשה הקודמת.","\u0003אלא אמר אביי: קרו שיתא\u0004 \u0005[קוראים שישה]\u0006 \u0003מ\"ואתה תצוה\"\u0004 וקוראים תחילת פרשת \"כי תשא\" \u0003עד \"ועשית\", וחד תני וקרי\u0004 \u0005[ואחד שונה וקורא]\u0006 \u0003מ\"כי תשא\" עד \"ועשית\"\u0004 כדי להבליט שקוראים זאת משום פרשת שקלים.","\u0003מיתיבי\u0004 \u0005[מקשים]\u0006 ממה ששנינו: \u0003חל להיות\u0004 ראש חודש אדר \u0003בפרשה הסמוכה לה,\u0004 לפרשת \"כי תשא\", \u0003בין מלפניה בין מלאחריה\u0004 — \u0003קורין אותה וכופלין אותה.\u0004","ועתה, \u0003בשלמא\u0004 \u0005[נניח]\u0006 \u0003ל\u0004שיטת \u0003אביי ניחא\u0004 \u0005[נוח\u0006 הדבר\u0005]\u0006 שהרי קוראים וכופלים, כפי שאמר, \u0003אלא לר' יצחק נפחא קשיא\u0004 \u0005[קשה]!\u0006","ומשיבים: \u0003אמר לך\u0004 \u0005[יכול היה לומר לך]\u0006 \u0003ר' יצחק נפחא: ולאביי מי ניחא\u0004 \u0005[האם\u0006 זה \u0005נוח]\u0006 באמת? \u0003תינח\u0004 \u0005[נניח]\u0006 שקורה הדבר \u0003לפניה,\u0004 בפרשת \"ואתה תצוה\", שאז קוראים בשבת זו את \"ואתה תצוה\" ואת תחילת פרשת \"כי תשא\", וחוזרים לקרוא אותה בפעם השניה בשבת שלאחר מכן, אבל \u0003לאחריה היכי משכחת לה\u0004 \u0005[איך מוצא אתה אותה]\u0006 שתהא פרשת שקלים אחרי פרשת \"כי תשא\"?","\u0003אלא מאי אית לך למימר\u0004 \u0005[מה יש לך לומר]\u0006 שיש להבין את הברייתא באופן אחר, ולהסביר: \u0003כופלה בשבתות\u0004 שקורא אותה פרשה פעמיים, בשתי שבתות סמוכות, \u0003הכא נמי\u0004 \u0005[כאן גם כן]\u0006 \"מלפניה\" הכוונה \u0003כופלה בשבתות.\u0004","ועוד בעיה דומה: ראש חודש אדר ש\u0003חל להיות ב\u0004פרשת \u0003\"כי תשא\" עצמה,\u0004 מה עושים? \u0003אמר ר' יצחק נפחא: קרו שיתא\u0004 \u0005[קוראים שישה]\u0006 מ\u0003\"ועשית\" עד \"ויקהל\"\u0004 שאין מתחילים את פרשת \"כי תשא\" בתחילתה בענין השקלים אלא בקטע שלאחר מכן, וגומרים פרשה זו, \u0003וחד קרי\u0004 \u0005[ואחד קורא]\u0006 \u0003מ\"כי תשא\" עד \"ועשית\",\u0004 שחוזר לתחילת הפרשה וקורא את פרשת שקלים.","\u0003מתקיף לה\u0004 \u0005[מקשה על כך]\u0006 \u0003אביי: השתא אמרי\u0004 \u0005[עכשיו יאמרו]\u0006 אנשים: \u0003למפרע\u0004 אחורנית \u0003הוא דקרי\u0004 \u0005[שקורא],\u0006 שיחשבו שדילגו בטעות על הקטע הראשון ועכשיו חוזרים ומשלימים אותו! \u0003אלא אמר אביי: קרו שיתא\u0004 \u0005[קוראים שישה]\u0006 כל פרשת \"כי תשא\" \u0003עד \"ויקהל\", וחד תני וקרי\u0004 \u0005[ואחד שונה וקורא]\u0006 \u0003מ\"כי תשא\" ועד \"ועשית\".\u0004","\u0003תניא כוותיה\u0004 \u0005[שנויה\u0006 ברייתא \u0005כשיטתו]\u0006 של \u0003אביי: חל\u0004 ראש חודש אדר \u0003להיות ב\u0004שבת שבה קוראים את פרשת \u0003\"כי תשא\" עצמה\u0004 — \u0003קורין אותה וכופלין אותה\u0004 את פרשת שקלים בשנית.","שנינו במשנה: שאם \u0003חל\u0004 ראש חודש אדר \u0003להיות בתוך השבת\u0004 (השבוע) — \u0003מקדימים\u0004 את קריאת פרשת שקלים \u0003לשבת שעברה. איתמר\u0004 \u0005[נאמר]\u0006 שחלקו אמוראים בבעיה הבאה: \u0003ראש חדש אדר שחל להיות בערב שבת,\u0004 מה עושים? \u0003רב אמר: מקדימין\u0004 וקוראים את פרשת שקלים בשבת האחרונה של חודש שבט, \u0003ושמואל אמר: מאחרין,\u0004 כלומר, קוראים אותה בשבת הקרובה, שהיא בשני באדר.","ומסבירים: \u0003רב אמר: מקדימין,\u0004 שאם תאמר שלא יקדימו, \u0003אם כן בצרי להו יומי\u0004 \u0005[יחסרו להם ימי]\u0006 ה\u0003שולחנות,\u0004 שהרי על השולחנים לשבת ולפרוט לציבור את הכספים המיועדים לשקלים שבועיים ימים (שתי שבתות) ואינם יושבים אלא עד חמישה עשר באדר, ואם ההודעה על השקלים היא רק בשני באדר, יתחילו אם כן להביא רק מהשלישי בו, ויחסרו מימי הבאת השקלים. \u0003ושמואל אמר: מאחרין,\u0004 וכנגד טענת רב \u0003אמר לך\u0004 \u0005[\u0006יכול היה \u0005לומר לך]:\u0006 \u0003סוף סוף\u0004 בשנה כזו \u0003חמיסר במעלי שבתא מיקלע\u0004 \u0005[חמישה עשר\u0006 באדר \u0005יחול בערב שבת]\u0006 \u0003ו\u0004ה\u0003שולחנות לא נפקי\u0004 \u0005[ייצאו]\u0006 מהמקום \u0003עד חד בשבא\u0004 \u0005[אחד,\u0006 יום ראשון \u0005בשבת]\u0006 ונמצא שישאר אותו זמן לשולחנות כבכל שנה, \u0003הלכך\u0004 \u0005[על כן]\u0006 \u0003מאחרין.\u0004","ומנסים להביא ראיות; \u0003תנן\u0004 \u0005[שנינו\u0006 במשנתנו\u0005]:\u0006 \u0003חל\u0004 ראש חודש אדר \u0003להיות בתוך השבת\u0004 (השבוע) — \u0003מקדימין\u0004 לקרוא את פרשת שקלים \u0003לשעבר,\u0004 בשבת שעברה, \u0003ומפסיקין\u0004 מלהמשיך את קריאת הפרשה השניה מארבע פרשיות \u0003לשבת אחרת,\u0004 אלא קוראים אותה בשבת שלאחריה. \u0003מאי לאו\u0004 \u0005[האם לא]\u0006 הכוונה \u0003אפילו\u0004 שחל \u0003בערב שבת,\u0004 וכרב? ודוחים: \u0003לא,\u0004 אפשר לומר \u0003בתוך השבת דוקא,\u0004 אבל מערב שבת כבר אינו קרוי \"בתוך השבת\" אלא ערב שבת.","ומציעים עוד, \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ראיה מברייתא: \u0003איזו היא שבת ראשונה\u0004 לפרשיות — \u0003כל שחל ראש חודש אדר להיות בתוכה, ואפילו בערב שבת. מאי לאו\u0004 \u0005[האם לא]\u0006 \u0003\"אפילו בערב שבת\" דומיא\u0004 \u0005[דומה]\u0006 להלכה אם חל להיות ב\u0003תוכה, מה\u0004 אם כשחל להיות ב\u0003תוכה מקדימין — אף\u0004 כשחל להיות ב\u0003ערב שבת מקדימין\u0004 וכרב!","\u0003אמר שמואל: בה.\u0004 כלומר, שמואל מתקן את הגירסה, וגורס \"שחל ראש חודש בה\" כלומר, ביום השבת עצמו, ולא שבת במובן שבוע. \u0003וכן תנא דבי\u0004 \u0005[שנה\u0006 החכם \u0005בבית\u0006 מדרשו\u0005]\u0006 של \u0003שמואל: \"בה\".\u0004","ומעירים: מחלוקת זו היא \u0003כתנאי\u0004 \u0005[כ\u0006מחלוקת \u0005תנאים]\u0006 שכבר נחלקו באותו ענין. ששנינו: \u0003מסרגין לשבתות,\u0004 כלומר, שבקריאת ארבע הפרשיות מדלגים על שבת אחת, ונמצאת קריאתן לסירוגין, אלו \u0003דברי ר' יהודה הנשיא, ר' שמעון בן אלעזר אומר: אין מסרגין. אמר ר' שמעון בן אלעזר: אימתי אני אומר\u0004 ש\u0003אין מסרגין\u0004 אלא קוראים לפי הסדר — \u0003בזמן שחל\u0004 ראש חודש אדר \u0003להיות בערב שבת\u0004 שאז אין מקדימים ונמצאות הפרשיות רצופות, \u0003אבל בזמן שחל להיות בתוך השבת מקדים וקורא משבת שעברה, אף על פי שהוא\u0004 עדיין חודש \u0003שבט,\u0004 הרי שהוא סבור כשיטת שמואל, ודעת רב כר' יהודה הנשיא.","שנינו במשנה: \u0003ב\u0004שבת ה\u0003שניה\u0004 של חודש אדר קורא פרשת \u0003\"זכור\". איתמר\u0004 \u0005[נאמר]\u0006 שנחלקו אמוראים בשאלה: \u0003פורים שחל להיות בערב בשבת,\u0004 מה עושים לגבי הקריאה? \u0003רב אמר: מקדימין\u0004 לקרוא \u0003פרשת \"זכור\"\u0004 בשבת שלפני פורים, \u0003ושמואל אמר: מאחרין\u0004 וקוראים בשבת שלאחר פורים.","ומסבירים, \u0003רב אמר: מקדימין\u0004 — \u0003כי היכי\u0004 \u0005[כדי]\u0006 ש\u0003לא תיקדום עשייה\u0004 של פורים \u0003לזכירה\u0004 של מחיית עמלק. \u0003ושמואל אמר: מאחרין,\u0004 וטעמו: \u0003אמר לך\u0004 \u0005[\u0006יכול היה \u0005לומר לך]\u0006 \u0003כיון דאיכא\u0004 \u0005[שיש]\u0006 את הכרכים ה\u0003מוקפין\u0004 חומה \u0003דעבדי בחמיסר\u0004 \u0005[שעושים\u0006 את פורים \u0005בחמישה עשר]\u0006 הרי לגביהם לפחות \u0003עשיה וזכירה בהדי הדדי קא אתיין\u0004 \u0005[ביחד הן באות].\u0006","\u0003תנן\u0004 \u0005[שנינו\u0006 במשנה\u0005]:\u0006 \u0003ב\u0004שבת ה\u0003שניה\u0004 קוראים את פרשת \u0003\"זכור\", והא כי מיקלע ריש ירחא\u0004 \u0005[והרי כאשר חל ראש חודש]\u0006 אדר להיות \u0003בשבת, מיקלע\u0004 \u0005[יחול]\u0006 \u0003פורים בערב שבת, וקתני\u0004 \u0005[שנינו]\u0006 כי \u0003ב\u0004שבת ה\u0003שניה\u0004 קוראים פרשת \u0003\"זכור\",\u0004 משמע שמקדימים, וכרב! \u0003אמר רב פפא:\u0004 אפשר לדחות ולפרש \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003שניה\u0004 — \u0003שניה להפסקה\u0004 שמפסיקים שבת אחת ולאחריה קוראים \"זכור\".","ומציעים: \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ראיה אחרת ממה ששנינו: \u0003איזו שבת שניה\u0004 — \u0003כל שחל פורים להיות בתוכה, אפילו בערב שבת.\u0004 ונדייק, \u0003מאי לאו\u0004 \u0005[האם לא]\u0006 הכוונה \u0003ערב שבת דומיא\u0004 \u0005[בדומה]\u0006 ל\u0003\"תוכה\", מה\u0004 כשחל פורים להיות ב\u0003תוכה מקדימין\u0004 וקוראים שבת קודם, \u0003אף\u0004 כשחל פורים ב\u0003ערב שבת מקדימין!\u0004","\u0003אמר שמואל:\u0004 יש לקרוא \"חל \u0003בה\",\u0004 ולא \"בתוכה\", כלומר שחל פורים ביום השבת. \u0003וכן תנא דבי\u0004 \u0005[שנה\u0006 החכם \u0005בבית\u0006 מדרשו\u0005]\u0006 של \u0003שמואל:\u0004 \u0005שמואל]:\u0006 חל פורים להיות \u0003בה.\u0004","\u0003חל\u0004 פורים \u0003להיות בשבת עצמה, אמר רב הונא: לדברי הכל אין מקדימים\u0004 אלא קוראים בו ביום אף לדברי רב. \u0003ורב נחמן אמר: עדיין היא מחלוקת,\u0004 שרב סבור שיש להקדים זכירה לעשיה ולא לעשותם בבת אחת ולכן יש להקדים ולקרוא פרשת שקלים בשבת שלפניה. \u0003איתמר נמי\u0004 \u0005[נאמר גם כן]\u0006 כיוצא בו בשם חכם אחר \u0003אמר ר' חייא בר אבא, אמר ר' אבא אמר רב: פורים שחל להיות בשבת\u0004 — \u0003מקדים וקורא בשבת שעברה\u0004 פרשת \u0003\"זכור\",\u0004 וכדברי רב נחמן.","שנינו במשנה: \u0003ב\u0004שבת ה\u0003שלישית\u0004 קוראים את הפרשה העוסקת בענין \u0003פרה אדומה. תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003איזו היא שבת שלישית\u0004 — \u0003כל שסמוכה לפורים מאחריה. איתמר\u0004 \u0005[נאמר]\u0006 כי \u0003ר' חמא בר' חנינא אמר: שבת הסמוכה לראש חודש ניסן.\u0004","ומעירים: \u0003ולא פליגי\u0004 \u0005[ואינם חלוקים]\u0006 בהלכה, אלא מדברים במקרים שונים: \u0003הא\u0004 \u0005[זה]\u0006 שאמר רבי חמא ברבי חנינא שקוראים אותה בשבת הסמוכה לראש חודש ניסן, הרי זה \u0003דאיקלע\u0004 \u0005[כשחל]\u0006 \u0003ראש חודש ניסן בשבת\u0004 עצמה, שאז קוראים פרשת החודש באותו יום (ועושים הפסקה בשבת שאחרי פורים) כדי לקרב את טהרת הפרה לזמן הקרבת הפסח, \u0003הא\u0004 \u0005[זה]\u0006 ששנינו בברייתא שקוראים אותה בשבת שאחרי הפורים, הרי זה \u0003דאיקלע\u0004 \u0005[כשחל]\u0006 ראש חודש להיות \u0003באמצע השבת\u0004 (השבוע) ולכן קוראים בשבת שלפני ראש חודש את פרשת \"החודש\", ובשבת הקודמת קוראים פרשת \"פרה\", ומפסיקים, ונמצא שקוראים \"פרה\" בשבת הסמוכה לפורים אחריו.","שנינו במשנה כי \u0003בשבת ה\u0004\u0003רביעית\u0004 קוראים \u0003\"החדש הזה לכם\". תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003ראש חודש אדר שחל להיות בשבת\u0004 — \u0003קורין\u0004 בה את פרשת \u0003\"כי תשא\" ומפטירים ב\"יהוידע\". ואיזו היא שבת ראשונה\u0004 — \u0003כל שחל ראש חודש אדר להיות בתוכה, ואפילו בערב שבת. בשניה\u0004 קוראים פרשת \u0003\"זכור\" ומפטירין \"פקדתי\u0004 את אשר עשה עמלק\u0003\"\u0004 (שמואל א' טו, א-לד), \u0003ואיזו היא שבת שניה\u0004 — \u0003כל שחל פורים להיות בתוכה ואפילו\u0004 כשחל להיות \u0003בערב שבת. בשלישית\u0004 קוראים את הפרשה העוסקם בענין","\u0003פרה אדומה, ומפטירין \"וזרקתי עליכם\u0004 מים טהורים\u0003\"\u0004 (יחזקאל לו, כה-לח), \u0003ואיזו היא שבת שלישית\u0004 — \u0003כל שסמוכה לפורים מאחריה. ברביעית\u0004 קוראים \u0003\"החדש הזה\u0004 לכם \u0003\"\u0004\u0003ומפטירין \"כה אמר ה' אלהים בראשון באחד לחדש\"\u0004 (יחזקאל מה, טז (יח) - מו, טו (יח))."],["\u0003ואיזו היא שבת רביעית — כל שחל ראש חדש ניסן להיות בתוכה, ואפילו בערב שבת.\u0004","שנינו במשנה: \u0003ב\u0004שבת ה\u0003חמישית חוזרין לכסדרן.\u0004 ושואלים: \u0003לסדר מאי\u0004 \u0005[\u0006של \u0005מה]\u0006 חוזרים? \u0003ר' אמי אמר: לסדר פרשיות הוא חוזר,\u0004 כלומר, שבכל אותם שבועות קראו רק את הפרשיות המיוחדות, ובחמישית חוזרים לסדר הפרשיות הקבוע. \u0003ר' ירמיה אמר: לסדר הפטרות הוא חוזר,\u0004 שכן רוב הקריאה היא כמו בשבת רגילה לפי סדר התורה, אלא שלמפטיר קוראים בפרשיות המיוחדות.","\u0003אמר אביי: כוותיה\u0004 \u0005[כשיטתו]\u0006 של \u0003ר' אמי מסתברא\u0004 \u0005[מסתבר]\u0006 לומר. \u0003דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005]:\u0006 \u0003לכל\u0004 הימים המיוחדים \u0003מפסיקין\u0004 ואין קוראים כסדר פרשת שבוע אלא בענין היום, הן \u0003לראשי חדשים, לחנוכה, ולפורים, לתעניות, ולמעמדות, וליום הכפורים,\u0004 שאם חל אחד מימים אלה בשבת, אין קוראים את סדר הקריאה הרגיל בשלימותו אלא קריאה המיוחדת לאותו היום.","\u0003בשלמא למאן דאמר\u0004 \u0005[נניח ל\u0006שיטת \u0005מי שאומר]\u0006 כי \u0003לסדר פרשיות הוא חוזר — היינו דאיכא\u0004 \u0005[הוא שיש]\u0006 \u0003פרשה\u0004 שנקראת גם \u0003בחול\u0004 (בשני וחמישי) ואליה חוזרים, ובימים אלו מפסיקים מהקריאה הרגילה וקוראים בפרשיות המיוחדות להם. \u0003אלא למאן דאמר\u0004 \u0005[ל\u0006שיטת \u0005מי שאומר]\u0006 כי \u0003לסדר הפטרות הוא חוזר — הפטרה בחול מי איכא\u0004 \u0005[האם יש]?\u0006 ואם כן לא שייך לומר מפסיקים.","\u0003ואידך\u0004 \u0005[והאחר]\u0006 מה הוא עונה לכך? לשיטתו — \u0003הא כדאיתא והא כדאיתא\u0004 \u0005[זו כמו שהיא וזו כמו שהיא],\u0006 כלומר, הדברים נאמרו באופן כללי, בימים שיש בהם הפטרה הכוונה לסדר הפטרות, ובימים של חול שאין בהם הפטרה הכוונה שחוזרים לסדר הקריאה הרגילה, ואם כן אין מכאן הוכחה.","ושואלים: \u0003ובתעניות למה לי הפסקה\u0004 כלל? \u0003ליקרי בצפרא בענינא דיומא\u0004 \u0005[שיקרא בבוקר בעניינו של יום]\u0006 לפי סדר הפרשות \u0003ובמנחה\u0004 שיקרא \u0003בתעניתא\u0004 \u0005[ב\u0006ענין \u0005התענית].\u0006 ומעירים: דבר זה \u0003מסייע ליה\u0004 \u0005[לו]\u0006 \u0003לרב הונא,\u0004 ש\u0003אמר רב הונא: מצפרא כינופיא\u0004 \u0005[מן הבוקר אסיפת\u0006 הציבור\u0005],\u0006 שכבר מן הבוקר היו אוספים את הקהל ובודקים את מעשיהם ומזהירים אותם על התשובה ועוסקים בשאר בעיות הציבור, ואין פנאי לקרוא בתורה.","ושואלים: \u0003היכי עבדינן\u0004 \u0005[כיצד עושים]\u0006 למעשה? \u0003אמר אביי: מצפרא לפלגיה דיומא מעיינינן במילי דמתא\u0004 \u0005[מן הבוקר עד חצי היום מעיינים אנו\u0006 ודנים \u0005בענייני העיר],\u0006 שמא יש דברים שצריך הציבור לתקן, שהרי יום התענית נועד בעיקרו לתקן את חטאי הציבור ופגמיו. \u0003מפלגיה דיומא לפניא\u0004 \u0005[מחצי היום לערב],\u0006 \u0003ריבעא דיומא קרא ומפטרי\u0004 \u0005[רבע היום קוראים\u0006 בתורה \u0005ומפטירים],\u0006 \u0003וריבעא דיומא בעו רחמי\u0004 \u0005[ורבע היום מבקשים רחמים]\u0006 \u0003שנאמר: \"ויקראו בספר תורת ה' אלהיהם רביעית היום ורביעית מתודים ומשתחוים\u0004 לה' אלהיהם\u0003\"\u0004 (נחמיה ט, ג).","ושואלים: \u0003ואיפוך אנא\u0004 \u0005[ו\u0006אולי \u0005אהפוך אני]\u0006 את הסדר שבחצי היום הראשון יעסקו בקריאה תפילה ווידוי? ומשיבים: \u0003לא סלקא דעתך\u0004 \u0005[לא יעלה על דעתך]\u0006 לומר זאת, \u0003דכתיב\u0004 \u0005[ש\u0006כן \u0005נאמר]\u0006 שם: \u0003\"ואלי יאספו כל חרד בדברי אלהי ישראל על מעל הגולה ואני ישב משומם עד למנחת הערב\"\u0004 (עזרא ט, ד) \u0003וכתיב\u0004 \u0005[ונאמר]:\u0006 \u0003\"ובמנחת הערב קמתי מתעניתי\u0004 ובקרעי בגדי ומעילי ואכרעה על ברכי ואפרשה כפי אל ה' אלהי\u0003\"\u0004 (עזרא ט, ה), הרי שהאסיפה בבוקר והתפילה בערב.","\u0003ב\u0004יום טוב ראשון של \u0003פסח קורין\u0004 (קוראים) \u0003בפרשת מועדות\u0004 האמורה בספר \u0003תורת כהנים\u0004 (ויקרא כב, כו - כג, ח). \u0003בעצרת\u0004 (חג השבועות) קוראים בענין היום \u0003\"שבעה שבעת\"\u0004 (ויקרא כג, טו-כב). \u0003בראש השנה\u0004 קוראים \u0003\"בחדש השביעי באחד לחדש\"\u0004 (ויקרא כג, כד). \u0003ביום הכפורים\u0004 קוראים \u0003\"אחרי מות\"\u0004 (ויקרא טז, א). \u0003ביום טוב\u0004 ה\u0003ראשון של חג\u0004 הסוכות \u0003קורין בפרשת מועדות שבתורת כהנים, ובשאר כל ימות החג\u0004 קוראים \u0003בקרבנות החג\u0004 שבספר במדבר (פרק כח, יב-לט).","\u0003בחנוכה\u0004 קוראים \u0003ב\u0004פרשת נדבת ה\u0003נשיאים\u0004 לחנוכת המשכן (במדבר פרק ז). \u0003בפורים\u0004 קוראים פרשת \u0003\"ויבא עמלק\"\u0004 (שמות יז, ח-טז). \u0003בראשי חדשים\u0004 קוראים \u0003\"ובראשי חדשיכם\"\u0004 (במדבר כח, יא-טו). ו\u0003במעמדות,\u0004 כאשר בכל פעם מתאסף חלק מן הציבור המקביל למשמר כהנים מסויים, ובכל עת שמשמר כהנים זה עובד, ישראלים השייכים למשמר זה קובעים אותו שבוע לתפילות ולתעניות, ויש בו גם קריאה מיוחדת בתורה, וקריאה זו היא \u0003ב\u0004פרשה העוסקת בענין \u0003מעשה בראשית\u0004 (בראשית א, א - ב, ג). \u0003בתעניות\u0004 קוראים בפרשת"],["\u0003ברכות וקללות\u0004 (ויקרא פרק כו). \u0003אין מפסיקין ב\u0004אמצע פרשת ה\u0003קללות\u0004 לקרוא לאדם אחר שישלים את קריאתה, \u0003אלא אחד קורא את כולן.\u0004","\u0003ב\u0004ימים \u0003שני ובחמישי\u0004 וכן \u0003בשבת במנחה קורין\u0004 (קוראים) \u0003כסדרן\u0004 לפי סדר הפרשות שבאותו שבוע, \u0003ואין עולים להם מן החשבון\u0004 כלומר, אין מה שקוראים נחשב שימשיכו לקרוא ממקום שהפסיקו בו, אלא חוזרים וקוראים מהיכן שהפסיקו בקריאת הבוקר בשבת שעברה. והקריאה שבינתיים אינה נחשבת.","ורמז לכך שקוראים במועדים מעניינו של יום — \u0003שנאמר: \"וידבר משה את מעדי ה' אל בני ישראל\"\u0004 (ויקרא כג, מד), כלומר, \u0003מצותן שיהו קורין\u0004 אותן (\"וידבר\") \u0003כל אחד ואחד בזמנו.\u0004","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003בפסח קורין בפרשת מועדות ומפטירין בפסח גלגל\u0004 (יהושע ה' ב-יד). ומעירים: \u0003והאידנא דאיכא תרי יומי\u0004 \u0005[ועכשיו שיש שני ימים טובים של פסח]\u0006 בחוץ לארץ, \u0003יומא קמא\u0004 \u0005[\u0006ב\u0005יום הראשון]\u0006 של פסח מפטירים \u0003בפסח גלגל, ולמחר — בפסח\u0004 שעשה \u0003יאשיהו\u0004 (מלכים ב' פרק כג).","\u0003ושאר ימות הפסח מלקט וקורא\u0004 בנושאים שונים \u0003מענינו של פסח\u0004 מכל מה שכתוב בתורה. ושואלים: \u0003מאי היא\u0004 \u0005[מה הוא]\u0006 שמלקטים? \u0003אמר רב פפא: מאפ\"ו\u0004 הוא \u0003סימן.\u0004 כלומר, \u0003\"מ\u0004 שכו וקחו לכם צאן\u0003\"\u0004 (שמות יב. כא ואילך) \u0003\"א\u0004ם כסף תלוה את עמי\u0003\"\u0004 (שמות כב, כד-כג, יט) \u0003\"פ\u0004סל לך\u0003\"\u0004 (שמות לד, א-כו) ו\u0003\"ו\u0004ידבר\u0003\"\u0004 (במדבר ט, א-טו).","ב\u0003יום טוב אחרון של פסח קורין \"ויהי בשלח\"\u0004 (שמות טו, א-כו), לפי שבו היתה קריעת ים סוף, \u0003ומפטירין \"וידבר דוד\"\u0004 (שמואל ב' פרק כב), שהוא שירת דוד. \u0003ולמחר\u0004 ביום השני (שהוא היום השמיני של פסח בחוץ לארץ) קוראים \u0003\"כל הבכור\"\u0004 (דברים טו, יט - טז, ח), \u0003ומפטירין \"עוד היום\"\u0004 (ישעיהו י, לב), מפני שמדבר שם בסנחריב, שמפלתו היתה בליל פסח.","\u0003אמר אביי: והאידנא\u0004 \u0005[ועכשיו,\u0006 בימינו\u0005]\u0006 \u0003נהוג עלמא למיקרי\u0004 \u0005[נוהגים הכל לקרוא]\u0006 באופן זה שסימנו: \u0003\"משך תורא, קדש בכספא, פסל במדברא, שלח בוכרא\"\u0004 \u0005[משוך שור, קדש בכסף, פסול במדבר, שלח בכור]\u0006 והוא בפרשיות הבאות: \"משכו וקחו לכם\", \"שור או כשב\" (פרשת המועדות ויקרא כב, כו - כג, מד), \"קדש לי כל בכור\", \"אם כסף תלווה את עמי\", \"פסל לך\", \"וידבר\" שבספר במדבר, \"בשלח פרעה את העם\", ו\"כל בכור\" שבספר דברים.","\u0003בעצרת\u0004 (בחג השבועות) קוראים \u0003\"שבעה שבועות\"\u0004 (דברים טו, יט - טז, יז) \u0003ומפטירין בחבקוק\u0004 (פרק ב) שיש בו הזכרת מעמד הר סיני. \u0003אחרים אומרים:\u0004 קוראים \u0003\"בחדש השלישי\"\u0004 (שמות יט, א-כ, כג) בענין מתן תורה, \u0003ומפטירין במרכבה\u0004 (יחזקאל פרק א). ומעירים: \u0003והאידנא דאיכא תרי יומי, עבדינן כתרוייהו\u0004 \u0005[ועכשיו\u0006 בימינו \u0005שיש\u0006 בחוץ לארץ \u0005שני ימים, עושים אנו כשניהם]\u0006 \u0003ואיפכא\u0004 \u0005[ולהיפך].\u0006 כלומר, נוהגים כאחרים ביום ראשון וכתנא קמא ביום שני.","\u0003בראש השנה\u0004 קוראים: \u0003\"\u0004ו\u0003בחדש השביעי\"\u0004 (במדבר פרק כט), \u0003ומפטירין: \"הבן יקיר לי אפרים\"\u0004 (ירמיהו לא, ב-כ). שנאמר שם \"זכור אזכרנו\", \u0003ויש אומרים\u0004 שקוראים: \u0003\"וה' פקד את שרה\"\u0004 (בראשית פרק כא), שלפי המסורת היה הדבר בראש השנה, \u0003ומפטירין\u0004 בענין דומה לו \u0003ב\u0004פרשת \u0003חנה\u0004 (שמואל א' א, א - ב, י).","\u0003והאידנא דאיכא תרי יומי\u0004 \u0005[ועכשיו\u0006 בימינו \u0005שיש שני ימים\u0006 של ראש השנה\u0005]\u0006 — \u0003יומא קמא\u0004 \u0005[היום הראשון]\u0006 של ראש השנה קוראים \u0003כיש אומרים,\u0004 ו\u0003למחר\u0004 קוראים \u0003\"והאלהים נסה את אברהם\"\u0004 (בראשית פרק כב), שמזכירים את זכות העקידה ביום הדין, \u0003ומפטירין \"הבן יקיר\".\u0004","\u0003ביום הכפורים קורין\u0004 פרשת \u0003\"אחרי מות\"\u0004 (ויקרא ט״ז:א׳), \u0003ומפטירין \"כי כה אמר רם ונשא\"\u0004 (ישעיהו נז, יד - נח, יד) העוסק בענייני צום ותשובה. \u0003ובמנחה קורין ב\u0004פרשת \u0003עריות\u0004 (ויקרא י״ח:י״א-י״ב) להודיע חומרת עבירות אלה, שאם חטא אדם בהן שישוב ביום הכיפורים. \u0003ומפטירין ב\u0004כל ספר \u0003יונה,\u0004 שמוזכרת שם התשובה של אנשי נינוה.","כיון שהוזכרה הפטרת יום הכיפורים מביאים מה ש\u0003אמר ר' יוחנן: כל מקום שאתה מוצא גבורתו של הקדוש ברוך הוא\u0004 נזכרת בכתוב, \u0003אתה מוצא ענוותנותו\u0004 כתובה בצידה. ו\u0003דבר זה כתוב בתורה, ושנוי בנביאים ומשולש בכתובים.\u0004","ומפרטים: \u0003כתוב בתורה\u0004 — שנאמר: \u0003\"כי ה' אלהיכם הוא אלהי האלהים ואדני האדנים\"\u0004 (דברים י, יז), \u0003וכתיב בתריה\u0004 \u0005[ונאמר אחריו]:\u0006 \u0003\"עשה משפט יתום ואלמנה\"\u0004 (דברים י, יח), הרי שהוא ענוותן ודואג לקטנים ולעלובים. \u0003שנוי בנביאים\u0004 — מצד אחד נאמר: \"כי \u0003כה אמר רם ונשא שכן עד וקדוש\u0004 שמו\" (ישעיהו נז, טו), \u0003וכתיב בתריה\u0004 \u0005[ונאמר אחריו]:\u0006 \u0003\"ואת דכא ושפל רוח\u0004 להחיות רוח שפלים ולהחיות לב נדכאים\u0003\"\u0004 (ישעיהו נז, טו). \u0003משולש בכתובים — דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"סלו לרכב בערבות ביה שמו\"\u0004 (תהלים סח, ה), \u0003וכתיב בתריה\u0004 \u0005[ונאמר אחריו]:\u0006 \u0003\"אבי יתומים ודין אלמנות\"\u0004 (תהלים סח, ו).","ושוב להמשך הברייתא: \u0003יום טוב הראשון של חג\u0004 הסוכות \u0003קורין בפרשת מועדות שבתורת כהנים\u0004 (ויקרא פרק כג), \u0003ומפטירין \"הנה יום בא לה'\"\u0004 (זכריה פרק יד), שבסיומו נזכר במיוחד חג הסוכות. \u0003והאידנא דאיכא תרי יומי\u0004 \u0005[ועכשיו שיש\u0006 בחוץ לארץ \u0005שני ימים],\u0006 \u0003למחר מיקרא הכי נמי קרינן\u0004 \u0005[לקרוא כך גם כן קוראים אנו]\u0006 שקוראים אנו אותו דבר, \u0003אפטורי מאי\u0004 \u0005[להפטיר מה]\u0006 אנו \u0003מפטירין\u0004 — \u0003\"ויקהלו אל המלך שלמה\"\u0004 (מלכים א' ח, ב-כא), על שם המאורע, שהיה בחג הסוכות.","\u0003ושאר כל ימות החג קורין בקרבנות\u0004 החג שבספר במדבר (פרק כט). ב\u0003יום טוב האחרון\u0004 של חג הסוכות (שמיני עצרת) \u0003קורין \"כל הבכור\"\u0004 (דברים טו, יט - טז, ט) ומתחילים ב\"עשר תעשר\" (יד, כב) לפי שיש בה הרבה \u0003מצות וחוקים\u0004 של מתנות עניים, להזכירם בימי שמחה, ומסיימים בפרשת \u0003בכור, ומפטירין\u0004 בפרשת \u0003\"ויהי ככלות שלמה\"\u0004 (מלכים א' ח, נד-סו) שהיתה באותו יום. \u0003ולמחר\u0004 ביום טוב שני של שמיני עצרת (שמחת תורה) \u0003קורין\u0004 ב\u0003\"וזאת הברכה\"\u0004 (דברים פרקים לג-לד), עד סוף התורה \u0003ומפטירין \"ויעמד שלמה\"\u0004 (מלכים א' ח, כב-לג).","\u0003אמר רב הונא אמר רב: שבת שחל להיות בחולו של מועד, בין בפסח, בין בסוכות\u0004 — \u0003מקרא קרינן\u0004 \u0005[לקרוא, קוראים אנו]\u0006 את פרשת \u0003\"ראה אתה\u0004 אומר אלי\u0003\"\u0004 (שמות לג, יב - לד, כו), שיש בה דיני הרגלים וחול המועד, ו\u0003אפטורי\u0004 \u0005[\u0006ו\u0005מפטירים]\u0006 \u0003בפסח\u0004 בפרשת \u0003\"העצמות היבשות\"\u0004 (יחזקאל לז, א-יד), שמדברת בענין הגאולה מן השעבוד. \u0003ובסוכות\u0004 מפטירים \u0003\"ביום בוא גוג\"\u0004 (יחזקאל לח, יח - לט, ט) המדברת על הגאולה לעתיד.","ו\u0003בחנוכה\u0004 קוראים בתורה \u0003ב\u0004פרשת ה\u0003נשיאים\u0004 שהביאו לחנוכת המשכן (במדבר פרק ז), \u0003ומפטירין בנרות\u0004 של \u0003זכריה\u0004 (זכריה ב, יד - ד, ז). \u0003ואי מיקלעי\u0004 \u0005[ואם מזדמנות]\u0006 \u0003שתי שבתות\u0004 בתוך חנוכה — \u0003קמייתא\u0004 \u0005[\u0006בשבת ה\u0005ראשונה]\u0006 קוראים \u0003בנרות\u0004 של \u0003זכריה, בתרייתא\u0004 \u0005[באחרונה]\u0006 \u0003בנרות שלמה\u0004 (מלכים א', פרק ז) המדברת במנורות המקדש.","\u0003בפורים\u0004 קוראים ב\u0003\"ויבא עמלק\"\u0004 (שמות יז, ח-טז). \u0003בראשי חדשים\u0004 קוראים \u0003\"ובראשי חדשיכם\"\u0004 (במדבר כח, יא). \u0003ראש חדש שחל להיות בשבת, מפטירין \"והיה מדי חדש בחדשו\u0004 ומדי שבת בשבתו\u0003\"\u0004 (ישעיהו פרק סו), שבסופה יש הזכרת שבת וראש חודש יחד. \u0003חל להיות\u0004 ראש חודש \u0003באחד בשבת\u0004 (ביום ראשון), \u0003מאתמול\u0004 בשבת ערב ראש חודש \u0003מפטירין \"ויאמר לו יהונתן מחר חדש\"\u0004 (שמואל א' כ, יח-מב), המספר על דבר שאירע בערב ראש חודש.","\u0003אמר רב הונא:\u0004"],["\u0003ראש חדש אב שחל להיות בשבת, מפטירין \"חדשיכם ומועדיכם שנאה נפשי היו עלי לטרח\"\u0004 (ישעיהו א, יד) ושואלים: \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"היו עלי לטרח\"\u0004 מה טירחה יש בדבר? ומסבירים: \u0003אמר הקדוש ברוך הוא: לא דיין להם לישראל שחוטאין לפני, אלא שמטריחין אותי לידע איזו גזירה קשה אביא עליהם,\u0004 שהרי אנשים אלה מתענים לבטל אותן גזירות.","ושואלים: \u0003בתשעה באב גופיה\u0004 \u0005[עצמו]\u0006 \u0003מאי מפטרינן\u0004 \u0005[מה אנו מפטירים]?\u0006 \u0003אמר רב: \"איכה היתה לזונה\"\u0004 (ישעיהו א, כא). ושואלים: \u0003מקרא מאי\u0004 \u0005[מה קוראים]\u0006 בתורה? \u0003תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005],\u0006 \u0003אחרים אומרים:\u0004 קוראים \u0003\"ואם לא תשמעו לי\"\u0004 (ויקרא כו, יד) \u0003ר' נתן בר יוסף אומר:\u0004 קוראים \u0003\"עד אנה ינאצני העם הזה\"\u0004 (במדבר יד, יא) \u0003ויש אומרים\u0004 שקוראים: \u0003\"עד מתי לעדה הרעה הזאת\"\u0004 (במדבר יד, כז). \u0003אמר אביי: האידנא נהוג עלמא למיקרי\u0004 \u0005[עכשיו נוהגים הכל לקרוא]\u0006 \u0003\"כי תוליד בנים\"\u0004 (דברים ד, כה-מ), \u0003ומפטירין \"אסף אסיפם\"\u0004 (ירמיהו ח, יג - ט, כג).","שנינו במשנה: \u0003במעמדות\u0004 קוראים \u0003במעשה בראשית,\u0004 ושואלים: \u0003מנהני מילי\u0004 \u0005[מנין הדברים הללו]\u0006 שקוראים במעמדות קריאה זו, ומה היא קשורה למעמדות? \u0003אמר ר' אמי: אלמלא מעמדות לא נתקיימו שמים וארץ, שנאמר: \"אם לא בריתי יומם ולילה חקות שמים וארץ לא שמתי\"\u0004 (ירמיהו לג, כה), שהקרבת הקרבנות יומם ולילה היא המקיימת את העולם.","\u0003וכתיב\u0004 \u0005[ונאמר]:\u0006 \u0003\"ויאמר ה' אלהים במה אדע כי אירשנה\"\u0004 (בראשית טו, ח), \u0003אמר אברהם לפני הקדוש ברוך הוא: רבונו של עולם, שמא חס ושלום ישראל חוטאים לפניך ואתה עושה להם כדור המבול וכדור הפלגה\u0004 ומשמיד אותם כליל? \u0003אמר לו: לאו\u0004 \u0005[לא].\u0006","\u0003אמר לפניו: רבונו של עולם, \"במה אדע\"? אמר לו: \"קחה לי עגלה משלשת\"\u0004 (בראשית טו, ט), כלומר, רמז לו שיקריבו קרבנות ויתרצו לפניו. \u0003אמר לפניו: רבונו של עולם, תינח\u0004 \u0005[נניח]\u0006 \u0003בזמן שבית המקדש קיים\u0004 ואז הקרבנות מכפרים עליהם, אולם \u0003בזמן שאין בית המקדש קיים מה תהא עליהם? אמר לו: כבר תקנתי להם סדר קרבנות,\u0004 כלומר שיקראו בתורה דיני קרבנות, \u0003כל זמן שקוראים בהן מעלה אני עליהן כאילו מקריבין לפני קרבן ומוחל אני על כל עונותיהם.\u0004","שנינו במשנה: \u0003בתעניות\u0004 קוראים את פרשת \u0003ברכות וקללות, ואין מפסיקין ב\u0004אמצע פרשת ה\u0003קללות\u0004 לקרוא לאדם אחר שישלים את הקריאה. ושואלים: \u0003מנא הני מילי\u0004 \u0005[מנין הדברים הללו]\u0006 שאין מפסיקים בקללות? \u0003אמר ר' חייא בר גמדא אמר ר' אסי:\u0004 ש\u0003אמר קרא\u0004 \u0005[הכתוב]:\u0006 \u0003\"מוסר ה' בני אל תמאס\u0004 ואל תקוץ בתוכחתו\u0003\"\u0004(משלי ג, יא), ואם מפסיק באמצע — נראה כאילו מאס בתוכחה.","\u0003ריש לקיש אמר: לפי שאין אומרים ברכה על הפורענות,\u0004 וכיון שמברך לפני הקריאה ואחרי הקריאה, צריך לברך על דבר שאינו פורענות. ושואלים: \u0003אלא היכי עביד\u0004 \u0005[כיצד\u0006 הוא \u0005עושה]?\u0006 שיוכל אף אדם אחד לברך על התוכחה? \u0003תנא\u0004 \u0005[שנה]\u0006 החכם בתוספתא: \u0003כשהוא מתחיל — מתחיל בפסוק שלפניהם, וכשהוא מסיים מסיים בפסוק שלאחריהם.\u0004","\u0003אמר אביי: לא שנו\u0004 הלכות אלה \u0003אלא בקללות שבתורת כהנים\u0004 (ספר ויקרא), \u0003אבל קללות שבמשנה תורה — פוסק\u0004 אם רוצה. \u0003מאי טעמא\u0004 \u0005[מה טעם\u0006 הדבר\u0005]\u0006 — \u0003הללו\u0004 שבספר ויקרא \u0003בלשון רבים אמורות\u0004 והן מכוונות לכל ישראל \u0003ומשה מפי הגבורה\u0004 (מפי ה') \u0003אמרן,\u0004 ולכן הן חמורות וקשות יותר, \u0003והללו\u0004 שבספר דברים \u0003בלשון יחיד אמורות, ומשה מפי עצמו אמרן\u0004 ככל ספר דברים.","מסופר: \u0003לוי בר בוטי הוה קרי וקא מגמגם קמיה\u0004 \u0005[היה קורא\u0006 בתורה \u0005והיה מגמגם\u0006 בלשונו כשהיה קורא \u0005לפני]\u0006 \u0003רב הונא בארורי\u0004 \u0005[את ה\"ארורין\"]\u0006 שבדברי התוכחה, שהיה קשה לו לומר דברים חמורים אלה. \u0003אמר לו\u0004 רב הונא: \u0003אכנפשך\u0004 \u0005[אם רצונך]\u0006 יכול אתה להפסיק, שכן ההלכה היא: \u0003לא שנו\u0004 שאין להפסיק בקללות, \u0003אלא\u0004 ב\u0003קללות שבתורת כהנים אבל שבמשנה תורה פוסק.\u0004","\u0003תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005],\u0006 \u0003ר' שמעון בן אלעזר אומר: עזרא תיקן להן לישראל שיהו קורין\u0004 (קוראים) \u0003קללות שבתורת כהנים קודם עצרת\u0004 (חג השבועות) \u0003ו\u0004קללות \u0003שבמשנה תורה קודם ראש השנה.\u0004 ושואלים: \u0003מאי טעמא\u0004 \u0005[מה טעם\u0006 הדבר\u0005]?\u0006 \u0003אמר אביי ואיתימא\u0004 \u0005[ויש אומרים]\u0006 שאמר זאת \u0003ריש לקיש: כדי שתכלה השנה וקללותיה\u0004 ולא תתחיל שנה חדשה בסימן קללה.","ושואלים: \u0003בשלמא\u0004 \u0005[נניח]\u0006 קללות \u0003שבמשנה תורה איכא\u0004 \u0005[יש\u0006 טעם\u0005]\u0006 בנימוק \u0003כדי שתכלה שנה וקללותיה. אלא שבתורת כהנים, אטו\u0004 \u0005[וכי]\u0006 \u0003עצרת ראש השנה היא?\u0004 ומשיבים: \u0003אין\u0004 \u0005[כן]\u0006 \u0003עצרת נמי\u0004 \u0005[גם כן]\u0006 \u0003ראש השנה היא. דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005]:\u0006 \u0003ובעצרת\u0004 נידונין \u0003על פירות האילן,\u0004 משמע שהוא ראש השנה לענין זה.","קצת בקשר לזה \u0003תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005],\u0006 \u0003ר' שמעון בן אלעזר אומר: אם יאמרו לך זקנים \"סתור\" וילדים\u0004 יאמרו \u0003\"בנה\" — סתור ואל תבנה,\u0004 אף שלכאורה הוא דבר של קלקול, \u0003מפני שסתירת זקנים\u0004 היא \u0003בנין, ובנין נערים\u0004 הוא \u0003סתירה. וסימן לדבר\u0004 — \u0003רחבעם בן שלמה\u0004 שלא הלך בעצת זקנים אלא בעצת הצעירים, ולא הכניע עצמו בפני העם, ולכן מרדו בו כל ישראל.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003מקום שמפסיקים\u0004 בקריאה \u0003בשבת שחרית\u0004 — \u0003שם קורין במנחה\u0004 בשבת, מקום שהפסיקו \u0003במנחה\u0004 — \u0003שם קורין בשני,\u0004 מקום שהפסיקו \u0003בשני — שם קורין בחמישי,\u0004 מקום שהפסיקו \u0003בחמישי — שם קורין לשבת הבאה,\u0004 אלו \u0003דברי ר' מאיר. ר' יהודה אומר: מקום שהפסיקו שבת שחרית — שם קורין במנחה ובשני ובחמישי ולשבת הבאה.\u0004","\u0003אמר ר' זירא: הלכה\u0004 היא שב\u0003מקום שמפסיקים בשבת שחרית — שם קורין במנחה ובשני ובחמישי ולשבת הבאה,\u0004 שחוזרים וקוראים אותם דברים עצמם שלוש פעמים וחוזרים וקוראים אותם עם כל הפרשה בשבת הבאה. ושואלים: מדוע הוצרך ר' זירא לומר את ההלכה במפורט, \u0003ולימא\u0004 \u0005[ושיאמר]\u0006 בפשטות: \u0003הלכה כר' יהודה!\u0004"],["ומשיבים: \u0003משום דאפכי להו\u0004 \u0005[\u0006שהיו \u0005שהפכו אותם]\u0006 וייחסו את דברי רבי יהודה לרבי מאיר, וכדי שלא יהיה מקום לטעות הוצרך לומר מה הוא תוכן ההלכה. \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 כשקורא בתורה, \u0003פותח\u0004 את הספר \u0003ורואה\u0004 את הדברים שהוא צריך לקרוא, \u0003גולל\u0004 (סוגר) את הספר \u0003ומברך, וחוזר ופותח וקורא,\u0004 אלו \u0003דברי ר' מאיר. ר' יהודה אומר: פותח ורואה ומברך וקורא.\u0004","","ושואלים: \u0003מאי טעמא\u0004 \u0005[מה הטעם]\u0006 של \u0003ר' מאיר?\u0004 ומשיבים: טעמו הוא \u0003כ\u0004פי שאמר \u0003עולא,\u0004 שכן \u0003אמר עולא: מפני מה אמרו הקורא בתורה לא יסייע למתורגמן,\u0004 אלא יניח למתורגמן לתרגם לבדו — \u0003כדי שלא יאמרו\u0004 העם כי ה\u0003תרגום כתוב בתורה, הכא נמי\u0004 \u0005[כאן גם כן]\u0006 תיקנו שיגלול את הספר \u0003כדי שלא יאמרו\u0004 הנוכחים כי \u0003ברכות כתובים בתורה.\u0004 ושואלים: \u0003ור' יהודה\u0004 אינו חושש לכך? ומשיבים: לדעתו \u0003תרגום\u0004 — \u0003איכא למיטעי\u0004 \u0005[יש\u0006 מקום \u0005לטעות]\u0006 בו, שכן אנשים יחשבו שדברים מסויימים כתובים בספר, \u0003ברכות — ליכא למיטעי\u0004 \u0005[אין\u0006 מקום \u0005לטעות]\u0006 שהרי שומעים אותן כמה וכמה פעמים.","","","\u0003אמר ר' זירא אמר רב מתנה: הלכה\u0004 היא ש\u0003פותח ורואה ומברך וקורא.\u0004 ושואלים: \u0003ולימא\u0004 \u0005[ושיאמר]\u0006 בפשטות: \u0003הלכה כר' יהודה!\u0004 ומשיבים: \u0003משום דאפכי להו\u0004 \u0005[ש\u0006היו \u0005שהפכו אותם]\u0006 וייחסו את דברי ר' יהודה לר' מאיר, ולכך היה צריך לפסוק הלכה ברורה. ועוד מביאים מה ש\u0003אמר ר' זירא אמר רב מתנה: הלוחות\u0004 (המקומות החלקים בספר התורה שבין עמוד לעמוד ומלמעלה ומלמטה. ר\"ח) \u0003והבימות\u0004 שעומדים עליהם כדי לקרוא — \u0003אין בהן משום קדושה.\u0004","ועוד בענין גלילה, \u0003אמר ר' שפטיה אמר רב יוחנן: הגולל ספר תורה\u0004 — \u0003צריך שיעמידנו על התפר,\u0004 כלומר, שיסיים את הגלילה באופן שיהא התפר נראה בחוץ, שאם ימתחנו יותר מדי לא יקרע הכתב אלא רק ייפרם התפר (ר\"ח).","\u0003ואמר ר' שפטיה אמר ר' יוחנן: הגולל ספר תורה\u0004 מענין לענין בלא שיסתייע באחר — מניחו על ברכיו וגוללו, וכש\u0003גוללו\u0004 — גוללו \u0003מבחוץ,\u0004 כלומר, אוחז בידות העמוד שחוצה לו וגוללו כלפי פנים, \u0003ואין גוללו מבפנים\u0004 כלפי חוץ, כדי שלא ישמט הספר מידו ויתגלגל לארץ.","\u0003וכשהוא מהדקו\u0004 לחזק את הגלילה — \u0003מהדקו מבפנים,\u0004 שאוחז בעמוד הסמוך לו \u0003ואינו מהדקו מבחוץ,\u0004 כדי שלא יסתיר בתוך כך את הכתב בזרועותיו, שמצוה שיראו העם את הכתב בשעת ההידוק (ראה מסכת סופרים פ\"ג ה\"י).","\u0003ואמר ר' שפטיה אמר ר' יוחנן: עשרה שקראו בתורה — הגדול שבהם גולל\u0004 את \u0003ספר\u0004 ה\u0003תורה,\u0004 שהוא הכיבוד החשוב ביותר, ו\u0003הגוללו נוטל שכר כולן,\u0004 ש\u0003אמר ר' יהושע בן לוי: עשרה שקראו בתורה — הגולל ספר תורה קיבל שכר כולן.\u0004 ותוהים: \u0003שכר כולן סלקא דעתך\u0004 \u0005[עולה על דעתך]\u0006 לומר? מדוע יפסידו כל אותם האנשים שכרם? \u0003אלא אימא\u0004 \u0005[אמור]:\u0006 \u0003קיבל שכר כנגד כולן.\u0004 וכיון שהוזכרו דברים אלה, מביאים עוד מה ש\u0003אמר ר' שפטיה אמר ר' יוחנן: מנין שמשתמשין בבת קול,\u0004 שאם מסתפק אדם אם לעשות דבר מסויים ושומע קול האומר \"כן\" או \"לא\", יכול הוא לראות בכך תשובה לספקותיו ואין בכך משום ניחוש, \u0003שנאמר: \"ואזניך תשמענה דבר מאחריך לאמר\u0004 זה הדרך לכו בו\u0003\"\u0004 (ישעיהו ל, כא). ומעירים, שאין שמים לב לכל בת קול, אלא \u0003הני מילי\u0004 \u0005[דברים אלו\u0006 אמורים\u0005]\u0006 דווקא כש\u0003שמע קל גברא במתא\u0004 \u0005[קול גבר בעיר],\u0006 שאיננו מצוי שם אלא בשדה, \u0003וקל איתתא בדברא\u0004 \u0005[ו\u0006כן אם שמע \u0005קול אשה בשדה],\u0006 ששם אין נשים מצויות, וכיון שאינו מצוי ונזדמן לו — יכול לסמוך עליו. ועוד \u0003והוא דאמר\u0004 \u0005[ש\u0006הקול \u0005אומר]\u0006 וכופל: \u0003\"הן\" \"הן\"\u0004 (\"כן\" \"כן\"), או \u0003דאמר\u0004 \u0005[ש\u0006הקול \u0005אומר]:\u0006 \u0003\"לאו\" \"לאו\"\u0004 \u0005[\"לא\" \"לא\"].\u0006 \u0003ואמר ר' שפטיה אמר ר' יוחנן: כל הקורא\u0004 בתורה \u0003בלא נעימה\u0004 (מנגינה) \u0003ושונה\u0004 משניות \u0003בלא זמרה — עליו הכתוב אומר: \"וגם אני נתתי להם חקים לא טובים\u0004 ומשפטים לא יחיו בהם\u0003\"\u0004 (יחזקאל כ, כה), שהלומד בנעימה מראה שהלימוד אהוב עליו. ועוד, שהנעימה מסייעת לזכור את הדברים.","","","\u0003מתקיף לה\u0004 \u0005[מקשה על כך]\u0006 \u0003אביי: משום דלא ידע לבסומי קלא\u0004 \u0005[שאינו יודע להנעים\u0006 את \u0005קולו]\u0006 \u0003\"משפטים לא יחיו בהם\" קרית ביה\u0004 \u0005[קורא אתה בו]?!\u0006 \u0003אלא\u0004 יש לפרש את הפסוק \u0003כ\u0004דברי \u0003רב משרשיא,\u0004 ש\u0003אמר: שני תלמידי חכמים היושבים בעיר אחת ואין נוחין זה את זה בהלכה\u0004 אלא רבים בענייני הלכה וגורמים מחלוקת — \u0003עליהם הכתוב אומר: \"וגם אני נתתי להם חקים לא טובים ומשפטים לא יחיו בהם\".\u0004 ושוב לענין ספר תורה: \u0003אמר ר' פרנך אמר ר' יוחנן: כל האוחז ספר תורה ערום\u0004 בלי חציצה, עונשו שהוא \u0003נקבר ערום.\u0004 ושואלים: \u0003ערום סלקא דעתך\u0004 \u0005[עולה על דעתך]\u0006 לומר, ומדוע יקברוהו בבזיון כזה? \u0003אלא אימא\u0004 \u0005[אמור]:\u0006 \u0003נקבר ערום בלא מצות.\u0004","","ושוב תוהים: \u0003בלא מצות סלקא דעתך\u0004 \u0005[עולה על דעתך]?!\u0006 וכי משום דבר זה תינטל ממנו זכות כל מצוותיו? \u0003אלא אמר אביי: נקבר ערום בלא אותה מצוה,\u0004 שאם עסק בלימוד או בקריאה, כיון שזלזל בספר התורה — אין המצוה נחשבת לו. \u0003אמר ר' ינאי בריה\u0004 \u0005[בנו]\u0006 של \u0003ר' ינאי סבא\u0004 \u0005[הזקן]\u0006 \u0003משמיה\u0004 \u0005[משמו]\u0006 של \u0003ר' ינאי רבה\u0004 \u0005[הגדול]:\u0006 \u0003מוטב תיגלל המטפחת\u0004 סביב ספר התורה אחר גלילתו \u0003ואל יגלל ספר תורה\u0004 כשהוא בתוך המטפחת.","","שנינו במשנה, נאמר: \u0003\"וידבר משה את מעדי ה' אל בני ישראל\"\u0004 (ויקרא כג, מד), ומכאן נלמד כי \u0003מצותן שיהיו קורין אותם כל אחד ואחד בזמנו. תנו רבנן\u0004 \u0005[שנו חכמים]\u0006 בהרחבה: \u0003משה תיקן להם לישראל שיהו שואלים\u0004 לחכמים \u0003ו\u0004כן \u0003דורשים בענינו של יום\u0004 של כל חג ומועד; \u0003הלכות פסח בפסח, הלכות עצרת\u0004 (שבועות) \u0003בעצרת, הלכות חג\u0004 סוכות \u0003בחג.\u0004",""]]};
